insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('fa859665-f08e-59ea-a4b4-3eb5abea4906', 'bc07333c-fdfc-54ae-92db-685e9d5e1167', 1, 'This is my friend. His name is Minh.', array['This is my friend. His name''s Minh.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('fa859665-f08e-59ea-a4b4-3eb5abea4906', 'vi', 'Đây là bạn tôi. Tên anh ấy là Minh.', array['Đây là bạn của tôi. Anh ấy tên là Minh.', 'Đây là bạn mình. Cậu ấy tên là Minh.']::text[], null, '923e347d71167006f1facad7f297b6f085288966') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('7f8077a4-10d4-5a7d-b923-f5e6d7562713', 'bc07333c-fdfc-54ae-92db-685e9d5e1167', 2, 'He''s from Vietnam.', array['He is from Vietnam.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('7f8077a4-10d4-5a7d-b923-f5e6d7562713', 'vi', 'Anh ấy đến từ Việt Nam.', array['Anh ấy là người Việt Nam.', 'Cậu ấy đến từ Việt Nam.']::text[], null, 'f789441965125880d728d06262bb6d1cd139527d') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('9296c32b-a4bc-5aee-b3c6-6c0973798d89', 'bc07333c-fdfc-54ae-92db-685e9d5e1167', 3, 'She''s my teacher. She is from England.', array['She is my teacher. She is from England.', 'She''s my teacher. She''s from England.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('9296c32b-a4bc-5aee-b3c6-6c0973798d89', 'vi', 'Cô ấy là giáo viên của tôi. Cô ấy đến từ nước Anh.', array['Cô ấy là cô giáo của tôi. Cô ấy là người Anh.', 'Cô ấy là giáo viên của tôi. Cô ấy đến từ Anh.']::text[], null, '02a0bf18834fa6f1ab7df0eb72a6b2cfbe958d20') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e0dd5e57-427b-5276-9f1b-1541fed17d97', 'bc07333c-fdfc-54ae-92db-685e9d5e1167', 4, 'Her name is Anna.', array['Her name''s Anna.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e0dd5e57-427b-5276-9f1b-1541fed17d97', 'vi', 'Tên cô ấy là Anna.', array['Cô ấy tên là Anna.']::text[], null, '3973dcde44507dad9848fdc6ace72b9f763c051a') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('c7f33581-6d94-526e-9ac6-eecabf0d32c3', 'bc07333c-fdfc-54ae-92db-685e9d5e1167', 5, 'Is he your friend? Yes, he is.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c7f33581-6d94-526e-9ac6-eecabf0d32c3', 'vi', 'Anh ấy là bạn của bạn à? Vâng, đúng vậy.', array['Anh ấy có phải là bạn của bạn không? Vâng, đúng vậy.', 'Cậu ấy là bạn của bạn phải không? Vâng, đúng rồi.']::text[], 'Trả lời ngắn dùng Yes, he is; không viết gọn thành Yes, he''s.', '80d6a0d60655b57e201dc3d82f9cb186001d07c7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c7f33581-6d94-526e-9ac6-eecabf0d32c3', 'en-US', 'Is he your friend? Yes, he is.', '{}'::text[], 'The short answer is Yes, he is. Do not say Yes, he''s.', '80d6a0d60655b57e201dc3d82f9cb186001d07c7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
