insert into public.lessons (id, unit_id, sort_order, kind) values ('571d8503-0bf7-57d5-990c-6e0728369903', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'introducing-yourself'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('571d8503-0bf7-57d5-990c-6e0728369903', 'vi', 'Chúng tôi, họ', 'We, you, they đi với are: we are, they are; viết gọn là we''re, they''re. Our là của chúng tôi, their là của họ. Us là chúng tôi khi đứng sau động từ: Excuse us.', 'They, their bắt đầu bằng âm /ð/: đặt đầu lưỡi giữa hai hàm răng rồi phát âm, không đọc thành /d/ hay /z/. They''re và their đọc giống hệt nhau. Student có trọng âm ở âm tiết đầu: STU-dent.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('571d8503-0bf7-57d5-990c-6e0728369903', 'en-US', 'We and they', 'Use are with we, you and they: we are, they are, or we''re, they''re. Our and their show who has something. Use us after a verb: Excuse us.', 'They and their start with /ð/: put your tongue between your teeth. They''re and their sound the same. In student, the first part is strong: STU-dent.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
