insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('130fba0b-b473-5f33-83e8-2403e279d5ab', '03120364-5438-5176-9a20-304c72d6ef9d', 2, 'He''s Mr. Smith, our new teacher.', array['He is Mr. Smith, our new teacher.', 'He''s Mr Smith, our new teacher.', 'He is Mr Smith, our new teacher.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('130fba0b-b473-5f33-83e8-2403e279d5ab', 'vi', 'Đó là thầy Smith, giáo viên mới của chúng tôi.', array['Ông ấy là ông Smith, giáo viên mới của chúng tôi.', 'Anh ấy là thầy Smith, thầy giáo mới của chúng tôi.']::text[], null, 'd1557ae1f3b132423996d92a1e5c23a1b9126ef6') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
