insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4699f3e0-626f-590e-9db5-67ed998701a7', 'vi', 'Chị gái tôi và con gái tôi là học sinh.', array['Em gái tôi và con gái tôi là học sinh.', 'Chị gái tôi và con gái tôi là sinh viên.', 'Em gái tôi và con gái tôi là sinh viên.', 'Chị tôi và con gái tôi đều là học sinh.']::text[], null, 'c97b2f95d35ad87885bee7740beb0833f5e48939') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
