insert into public.lessons (id, unit_id, sort_order, kind) values ('76680d78-dc0c-57f8-b9f2-5af18ec3bfd1', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'family'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('76680d78-dc0c-57f8-b9f2-5af18ec3bfd1', 'vi', 'Tôi có, anh ấy có', 'I, you, we, they đi với have; he, she đi với has: I have a son. She has a baby. Child có số nhiều đặc biệt là children, không thêm -s. Only child là con một.', 'Have đọc /hæv/, has đọc /hæz/: đọc rõ âm cuối /v/ và /z/. Child đọc /tʃaɪld/ nhưng children đọc /ˈtʃɪldrən/: âm ai đổi thành âm i. Husband nhấn vào âm đầu: HUS-band.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('76680d78-dc0c-57f8-b9f2-5af18ec3bfd1', 'en-US', 'I have, he has', 'Use have with I, you, we and they. Use has with he and she. The plural of child is children. An only child has no brothers or sisters.', 'Say the last sound in have /v/ and has /z/. Child and children sound different: CHILD, CHIL-dren. In husband, the first part is strong: HUS-band.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
