insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e5aad5a0-0267-5588-b42f-5c1d4351139b', '76680d78-dc0c-57f8-b9f2-5af18ec3bfd1', 1, 'I have two children, a son and a daughter.', array['I have 2 children, a son and a daughter.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e5aad5a0-0267-5588-b42f-5c1d4351139b', 'vi', 'Tôi có hai con, một con trai và một con gái.', array['Tôi có hai đứa con, một trai một gái.', 'Tôi có hai người con, một con trai và một con gái.', 'Tôi có hai đứa con, một con trai và một con gái.']::text[], null, '81261643280cb893daeaa8d90d12895ed7d8bc3e') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('8ba7d543-a38a-5605-abcf-74c07553ed4c', '76680d78-dc0c-57f8-b9f2-5af18ec3bfd1', 2, 'She has a husband and a baby.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('8ba7d543-a38a-5605-abcf-74c07553ed4c', 'vi', 'Cô ấy có chồng và một em bé.', array['Cô ấy có một người chồng và một em bé.', 'Chị ấy có chồng và một em bé.', 'Cô ấy có chồng và một đứa con nhỏ.']::text[], null, 'dc2ec5e176d1220dccc03b0a3a8ca735eb5507f3') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('8fc820fd-cf68-53f7-9ffa-0a7a2b8df70f', '76680d78-dc0c-57f8-b9f2-5af18ec3bfd1', 3, 'He''s my husband, and I''m his wife.', array['He is my husband, and I am his wife.', 'He''s my husband and I''m his wife.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('8fc820fd-cf68-53f7-9ffa-0a7a2b8df70f', 'vi', 'Anh ấy là chồng tôi, còn tôi là vợ anh ấy.', array['Anh ấy là chồng tôi và tôi là vợ anh ấy.', 'Anh ấy là chồng của tôi, còn tôi là vợ của anh ấy.']::text[], null, '1964289129e0515e45f6fe4c3948128aaebe345b') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
