insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e67e7cd3-ed29-56d7-8779-cc935a97dae8', 'vi', 'Đó là chú của bạn à? Không, đó là anh họ tôi.', array['Đó có phải là chú của bạn không? Không, đó là anh họ của tôi.', 'Người đó là chú của bạn à? Không, đó là anh họ tôi.', 'Đó là bác của bạn à? Không, đó là anh họ tôi.', 'Anh ấy là chú của bạn à? Không, anh ấy là anh họ tôi.', 'Anh ấy là cậu của bạn à? Không, anh ấy là anh họ tôi.', 'Anh ấy là chú của bạn à? Không, anh ấy là em họ tôi.']::text[], null, 'ca57cf5e9d00a48172d78fc2595212af58273735') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
