insert into public.lessons (id, unit_id, sort_order, kind) values ('1c07ee0e-0683-511b-8933-03eb874df379', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'family'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('1c07ee0e-0683-511b-8933-03eb874df379', 'vi', 'Tả người', 'Tả người dùng be + tính từ: My brother is tall. Tả tóc, mắt dùng have hoặc has: He has brown eyes. Tính từ đứng trước danh từ: long hair, không nói hair long. Look + tính từ là trông có vẻ: You look young.', 'Hair đọc /hɛr/, cong lưỡi ở cuối; đừng đọc thành hai âm "he-a". Eye đọc giống hệt chữ I: /aɪ/. Look đọc /lʊk/ với âm u ngắn, đừng kéo dài. Funny nhấn vào âm đầu: FUN-ny.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('1c07ee0e-0683-511b-8933-03eb874df379', 'en-US', 'Describing people', 'Use be + adjective: My brother is tall. Use have or has for hair and eyes: He has brown eyes. The adjective comes before the noun: long hair. Look + adjective means seem: You look young.', 'In hair, curl your tongue at the end. Eye sounds like the letter I. Look has a short u sound. In funny, the first part is strong: FUN-ny.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('75f38a4f-1c5d-5ef0-8d81-1f0c39e0e6eb', (select id from public.courses where slug = 'english'), 'young', 'adjective', '/ˈjəŋ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
