insert into public.lessons (id, unit_id, sort_order, kind) values ('9c0eeefc-cbd1-5326-8864-ffa7179bd052', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'jobs'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9c0eeefc-cbd1-5326-8864-ffa7179bd052', 'vi', 'Bạn làm nghề gì', 'Nói nghề luôn cần a hoặc an: I''m a doctor (không nói I''m doctor). Dùng an trước nghề bắt đầu bằng âm nguyên âm: an engineer. Hỏi nghề: What do you do? (Bạn làm nghề gì?). Hỏi có hay không thì đặt do lên đầu: Do you work in an office? Trả lời: Yes, I do (không nói Yes, I am).', 'Job /dʒɑb/ và engineer /ˌɛndʒəˈnɪr/ có âm /dʒ/: môi hơi tròn và đẩy ra, mặt lưỡi chạm lợi sau răng trên rồi bật ra, cổ họng rung. Tiếng Việt không có âm này; đừng đọc job thành "giốp". Chữ o trong job, doctor đọc /ɑ/, mở miệng gần như "a". Engineer nhấn âm cuối: en-gi-NEER; doctor, office nhấn âm đầu: DOC-tor, OF-fice.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('9c0eeefc-cbd1-5326-8864-ffa7179bd052', 'en-US', 'What do you do?', 'Use a or an before a job: I''m a doctor. Use an before a vowel sound: an engineer. Ask about a job with What do you do? Ask yes or no questions with do: Do you work in an office? Yes, I do.', 'Job and engineer have the /dʒ/ sound: round your lips a little, touch the top of your mouth behind your teeth, then let go. The o in job and doctor sounds like ah. Say en-gi-NEER, DOC-tor, OF-fice.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('64100044-7e78-55ec-b7ee-640c8f0415cd', (select id from public.courses where slug = 'english'), 'do', 'verb', '/ˈdu/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('64100044-7e78-55ec-b7ee-640c8f0415cd', 'vi', 'làm', array['làm']::text[], 'Trong What do you do?, chữ do thứ nhất dùng để hỏi, chữ do thứ hai là làm. He, she dùng does: What does she do?', 'eadcd9bd2a09c75aef04954e6799e50278ee124a') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('64100044-7e78-55ec-b7ee-640c8f0415cd', 'en-US', 'to carry out an action; also a helper word in questions', '{}'::text[], 'In What do you do?, the first do helps make the question and the second do is the main verb. Use does with he and she.', 'eadcd9bd2a09c75aef04954e6799e50278ee124a') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('cd02b2c5-7f3c-53e5-8fda-ea5eb936096d', (select id from public.courses where slug = 'english'), 'job', 'noun', '/ˈdʒɑb/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('cd02b2c5-7f3c-53e5-8fda-ea5eb936096d', 'vi', 'công việc, nghề', array['công việc', 'việc', 'việc làm', 'nghề', 'nghề nghiệp']::text[], 'Job đếm được nên cần a: I have a new job (không nói I have new job).', '2eda8ad1632af052b0c74d6fcab6058b3a79cf25') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('cd02b2c5-7f3c-53e5-8fda-ea5eb936096d', 'en-US', 'the work you do to get money', '{}'::text[], 'Job takes a or an: I have a new job.', '2eda8ad1632af052b0c74d6fcab6058b3a79cf25') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('e21cb76b-4b5e-5bbd-bcc4-9f88e5d7d981', (select id from public.courses where slug = 'english'), 'work', 'verb', '/ˈwɝk/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('e21cb76b-4b5e-5bbd-bcc4-9f88e5d7d981', 'vi', 'làm việc', array['làm việc', 'làm']::text[], 'He, she dùng works: She works in an office. Work còn là danh từ (công việc) nhưng không dùng a: nói a job, không nói a work.', 'e274eeff768c6396088ec6eb091f4bf4d47ab1e0') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('e21cb76b-4b5e-5bbd-bcc4-9f88e5d7d981', 'en-US', 'to do a job', '{}'::text[], 'With he and she, add -s: She works in an office. Say a job, not a work.', 'e274eeff768c6396088ec6eb091f4bf4d47ab1e0') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
