insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('4d1c3e74-54f1-56d6-84e2-d7cfd7e81d20', '9c0eeefc-cbd1-5326-8864-ffa7179bd052', 1, 'What do you do? I''m a doctor.', array['What do you do? I am a doctor.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4d1c3e74-54f1-56d6-84e2-d7cfd7e81d20', 'vi', 'Bạn làm nghề gì? Tôi là bác sĩ.', array['Bạn làm nghề gì? Tôi làm bác sĩ.', 'Bạn làm nghề gì vậy? Tôi là bác sĩ.', 'Bạn làm công việc gì? Tôi là bác sĩ.', 'Bạn làm nghề gì? Mình là bác sĩ.', 'Anh làm nghề gì? Tôi là bác sĩ.', 'Chị làm nghề gì? Tôi là bác sĩ.']::text[], 'What do you do? hỏi về nghề nghiệp, không phải hỏi bạn đang làm gì lúc này.', '9c3a5f734df33ed245f0572f89ddf67aa6565cc3') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4d1c3e74-54f1-56d6-84e2-d7cfd7e81d20', 'en-US', 'What do you do? I''m a doctor.', '{}'::text[], 'What do you do? asks about your job, not about what you are doing now.', '9c3a5f734df33ed245f0572f89ddf67aa6565cc3') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('4b32ad67-b045-5aa4-9293-7cc228928247', '9c0eeefc-cbd1-5326-8864-ffa7179bd052', 2, 'My wife is a nurse, and I''m an engineer.', array['My wife is a nurse, and I am an engineer.', 'My wife is a nurse and I''m an engineer.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4b32ad67-b045-5aa4-9293-7cc228928247', 'vi', 'Vợ tôi là y tá, còn tôi là kỹ sư.', array['Vợ tôi là y tá và tôi là kỹ sư.', 'Vợ tôi làm y tá, còn tôi là kỹ sư.', 'Vợ tôi là điều dưỡng, còn tôi là kỹ sư.', 'Vợ tôi là y tá, còn tôi là kĩ sư.', 'Vợ của tôi là y tá, còn tôi là kỹ sư.', 'Vợ tôi làm y tá, còn tôi làm kỹ sư.']::text[], 'A nurse nhưng an engineer, vì engineer bắt đầu bằng âm nguyên âm.', '032e0558510e904053728b73209acefb9d36a75a') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('4b32ad67-b045-5aa4-9293-7cc228928247', 'en-US', 'My wife is a nurse, and I''m an engineer.', '{}'::text[], 'Say a nurse but an engineer, because engineer starts with a vowel sound.', '032e0558510e904053728b73209acefb9d36a75a') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('70853628-0b09-5ea9-aa14-d57a4f20dbea', '9c0eeefc-cbd1-5326-8864-ffa7179bd052', 3, 'Do you work in an office? Yes, I do.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('70853628-0b09-5ea9-aa14-d57a4f20dbea', 'vi', 'Bạn có làm việc ở văn phòng không? Vâng, có.', array['Bạn có làm việc ở văn phòng không? Có.', 'Bạn có làm việc trong văn phòng không? Có.', 'Bạn có làm việc ở văn phòng không? Có, tôi có.', 'Bạn làm việc ở văn phòng à? Vâng, đúng vậy.', 'Bạn có làm việc ở văn phòng không? Vâng, đúng vậy.', 'Bạn có làm văn phòng không? Có.', 'Bạn làm ở văn phòng à? Vâng.']::text[], 'Câu hỏi bắt đầu bằng Do thì trả lời ngắn bằng do: Yes, I do. Không trả lời Yes, I am.', '2835c3d0fdb8ed1c5ee9afd60a2bda06a7d8368d') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('70853628-0b09-5ea9-aa14-d57a4f20dbea', 'en-US', 'Do you work in an office? Yes, I do.', '{}'::text[], 'Answer a Do question with do: Yes, I do. Do not say Yes, I am.', '2835c3d0fdb8ed1c5ee9afd60a2bda06a7d8368d') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('1c443654-f820-584f-985e-52a10d7b30d5', '9c0eeefc-cbd1-5326-8864-ffa7179bd052', 4, 'I have a new job in Hanoi.', array['I have a new job in Ha Noi.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('1c443654-f820-584f-985e-52a10d7b30d5', 'vi', 'Tôi có công việc mới ở Hà Nội.', array['Tôi có một công việc mới ở Hà Nội.', 'Tôi có việc làm mới ở Hà Nội.', 'Tôi có việc mới ở Hà Nội.', 'Mình có công việc mới ở Hà Nội.', 'Tôi có một công việc mới tại Hà Nội.']::text[], null, 'e4288da3cc796d13b418a4f049c1cae7c7c51c73') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('6ecfcf3e-bafb-5ae8-ae50-dbf2fca20355', '9c0eeefc-cbd1-5326-8864-ffa7179bd052', 5, 'Is your mother a doctor? No, she''s a nurse.', array['Is your mother a doctor? No, she is a nurse.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('6ecfcf3e-bafb-5ae8-ae50-dbf2fca20355', 'vi', 'Mẹ bạn là bác sĩ à? Không, mẹ tôi là y tá.', array['Mẹ bạn có phải là bác sĩ không? Không, mẹ tôi là y tá.', 'Mẹ của bạn là bác sĩ à? Không, mẹ tôi là y tá.', 'Mẹ bạn là bác sĩ phải không? Không, mẹ tôi là y tá.', 'Mẹ bạn là bác sĩ à? Không, mẹ là y tá.', 'Mẹ bạn là bác sĩ à? Không, bà ấy là y tá.', 'Mẹ bạn là bác sĩ à? Không, mẹ tôi là điều dưỡng.', 'Mẹ bạn là bác sĩ à? Không, mẹ tôi làm y tá.']::text[], null, 'cd5104325960998a6606becebf3886d78aa645ab') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
