insert into public.lessons (id, unit_id, sort_order, kind) values ('4de68773-7a89-51c2-aa50-76bbf565f4f2', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'jobs'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('4de68773-7a89-51c2-aa50-76bbf565f4f2', 'vi', 'Thêm nghề', 'Hỏi nghề của he, she dùng does: What does he do? He''s a driver. Câu khẳng định với he, she thì động từ thêm -s: She works at a hospital. Câu hỏi thì -s chuyển sang does, động từ giữ nguyên: Does she work at night? (không nói Does she works). At chỉ nơi chốn hoặc thời điểm: at a hospital, at night.', 'Phân biệt /ʃ/ và /s/ trong She''s a singer: she /ʃi/ tròn môi, đẩy hơi như khi suỵt; singer /ˈsɪŋɚ/ môi dẹt, hơi đi qua kẽ răng như tiếng xì. Singer không có âm /g/: SING-er. Đuôi -er trong driver, farmer, waiter đọc /ɚ/ nhẹ, cong lưỡi. Trong waiter, chữ t đọc rất nhanh, gần như /d/: /ˈweɪɾɚ/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('4de68773-7a89-51c2-aa50-76bbf565f4f2', 'en-US', 'More jobs', 'Ask about he and she with does: What does he do? In a statement, add -s: She works at a hospital. In a question, use does and no -s: Does she work at night? Use at for a place or a time: at a hospital, at night.', 'She has /ʃ/: round your lips, like shh. Singer has /s/: keep your lips flat, like a snake. Do not say a g in singer. Say the -er ending softly. In waiter, the t sounds like a quick d.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
