insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('93f32851-6873-5553-864b-e5a97c268067', 'vi', 'đầu bếp, người nấu ăn', array['đầu bếp', 'người nấu ăn', 'người nấu bếp']::text[], 'Người nấu ăn là cook, không phải cooker. Cooker là đồ dùng để nấu: rice cooker là nồi cơm điện.', 'f3ba4d993e2dbcd87a6390a0cd67e6eab0b01a18') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('93f32851-6873-5553-864b-e5a97c268067', 'en-US', 'a person whose job is to make food', '{}'::text[], 'A cook is a person. A cooker is a thing you cook with, like a rice cooker.', 'f3ba4d993e2dbcd87a6390a0cd67e6eab0b01a18') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
