insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('5c9fcd0e-dbea-529d-942d-47203e888522', 'vi', 'người phục vụ bàn (nam)', array['người phục vụ', 'phục vụ bàn', 'người phục vụ bàn', 'nhân viên phục vụ', 'bồi bàn']::text[], 'Waiter thường chỉ nam, nữ là waitress. Người Mỹ cũng hay dùng server cho cả nam và nữ.', 'bda55eb01505bf9c8d7684bcb0c1f1124f64efa9') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('5c9fcd0e-dbea-529d-942d-47203e888522', 'en-US', 'a man who brings food to people in a restaurant', '{}'::text[], 'A woman is often called a waitress. Americans also say server for both.', 'bda55eb01505bf9c8d7684bcb0c1f1124f64efa9') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
