insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('b0c06708-bebf-52da-9ae8-ee2a073ed3ce', 'vi', 'ở, tại; vào, lúc (thời điểm)', array['ở', 'tại', 'vào', 'lúc']::text[], 'Work at + nơi làm việc: at a hospital. At night là vào ban đêm.', '27e90dfa57c358acfaf470860f6f72c9282ce995') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
