insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('d2a863e3-a932-5a71-8315-db2dc63b45b9', '4de68773-7a89-51c2-aa50-76bbf565f4f2', 1, 'What does your father do? He''s a farmer.', array['What does your father do? He is a farmer.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('d2a863e3-a932-5a71-8315-db2dc63b45b9', 'vi', 'Bố bạn làm nghề gì? Bố tôi là nông dân.', array['Bố của bạn làm nghề gì? Bố tôi là nông dân.', 'Bố bạn làm nghề gì? Ông ấy là nông dân.', 'Bố bạn làm nghề gì? Bố tôi làm nông.', 'Bố bạn làm nghề gì? Bố là nông dân.', 'Ba bạn làm nghề gì? Ba tôi là nông dân.', 'Bố bạn làm gì? Bố tôi là nông dân.']::text[], 'Với he, she dùng does, và chữ do phía sau giữ nguyên: What does he do? (không nói What does he does).', '80c70782ef24d3fb09cf46d5e68e736c48643a95') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('d2a863e3-a932-5a71-8315-db2dc63b45b9', 'en-US', 'What does your father do? He''s a farmer.', '{}'::text[], 'Say What does he do?, not What does he does?', '80c70782ef24d3fb09cf46d5e68e736c48643a95') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('bee8fd2c-94a4-57a4-83d6-2bd4d925fd81', '4de68773-7a89-51c2-aa50-76bbf565f4f2', 2, 'My mother works at a hospital. She''s a nurse.', array['My mother works at a hospital. She is a nurse.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('bee8fd2c-94a4-57a4-83d6-2bd4d925fd81', 'vi', 'Mẹ tôi làm việc ở một bệnh viện. Mẹ là y tá.', array['Mẹ tôi làm việc ở bệnh viện. Mẹ là y tá.', 'Mẹ tôi làm việc tại một bệnh viện. Mẹ là y tá.', 'Mẹ tôi làm ở bệnh viện. Mẹ là y tá.', 'Mẹ tôi làm việc ở một bệnh viện. Mẹ tôi là y tá.', 'Mẹ tôi làm việc ở bệnh viện. Mẹ là điều dưỡng.', 'Mẹ tôi làm việc ở bệnh viện. Mẹ tôi là y tá.']::text[], null, '59b91fda81061e8343e62fa2fb231a923b8f5fe1') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5ca003f2-d4fb-5f19-9f2b-8a56760953ff', '4de68773-7a89-51c2-aa50-76bbf565f4f2', 3, 'Is he a cook? No, he''s a waiter.', array['Is he a cook? No, he is a waiter.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5ca003f2-d4fb-5f19-9f2b-8a56760953ff', 'vi', 'Anh ấy là đầu bếp à? Không, anh ấy là người phục vụ.', array['Anh ấy có phải là đầu bếp không? Không, anh ấy là người phục vụ.', 'Anh ấy là đầu bếp à? Không, anh ấy là bồi bàn.', 'Anh ấy là đầu bếp à? Không, anh ấy là nhân viên phục vụ.', 'Anh ấy là đầu bếp à? Không, anh ấy là người phục vụ bàn.', 'Anh ấy là đầu bếp à? Không, anh ấy chạy bàn.', 'Cậu ấy là đầu bếp à? Không, cậu ấy là người phục vụ.']::text[], null, '0bc7d4f8335ab742f451edf283ad00afa35a3b6d') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('7ddce4f9-df39-5534-8e77-3e1ff5a37571', '4de68773-7a89-51c2-aa50-76bbf565f4f2', 4, 'She''s a singer, and her husband is a driver.', array['She is a singer, and her husband is a driver.', 'She''s a singer and her husband is a driver.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('7ddce4f9-df39-5534-8e77-3e1ff5a37571', 'vi', 'Cô ấy là ca sĩ, còn chồng cô ấy là tài xế.', array['Cô ấy là ca sĩ và chồng cô ấy là tài xế.', 'Cô ấy là ca sĩ, còn chồng cô ấy là lái xe.', 'Cô ấy là ca sĩ, còn chồng cô ấy làm tài xế.', 'Cô ấy là ca sĩ, còn chồng của cô ấy là tài xế.', 'Chị ấy là ca sĩ, còn chồng chị ấy là tài xế.']::text[], null, 'ec6f3049d4cf11fc19092813d181575ab05526dd') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('88278d45-61ca-5885-8af6-5cc904c5310c', '4de68773-7a89-51c2-aa50-76bbf565f4f2', 5, 'Does your husband work at night? Yes, he does.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('88278d45-61ca-5885-8af6-5cc904c5310c', 'vi', 'Chồng bạn có làm việc ban đêm không? Có.', array['Chồng bạn có làm việc vào ban đêm không? Có.', 'Chồng bạn có làm đêm không? Có.', 'Chồng bạn có làm ca đêm không? Có.', 'Chồng bạn có làm việc ban đêm không? Vâng, có.', 'Chồng bạn có làm việc ban đêm không? Có, anh ấy có.', 'Chồng của bạn có làm việc ban đêm không? Có.', 'Chồng bạn làm việc ban đêm à? Vâng, đúng vậy.']::text[], 'Sau Does, động từ không thêm -s: Does he work? (không nói Does he works). Trả lời ngắn: Yes, he does.', '448ad4ea92f94788132feb062db9e8b523c3bc66') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('88278d45-61ca-5885-8af6-5cc904c5310c', 'en-US', 'Does your husband work at night? Yes, he does.', '{}'::text[], 'After Does, the verb has no -s: Does he work? Answer: Yes, he does.', '448ad4ea92f94788132feb062db9e8b523c3bc66') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
