insert into public.lessons (id, unit_id, sort_order, kind) values ('22b58933-dc45-5b5e-b5ea-897c64d02693', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'jobs'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('22b58933-dc45-5b5e-b5ea-897c64d02693', 'vi', 'Nơi làm việc', 'Hỏi nơi làm việc: Where do you work? Where does she work? Trả lời: work at hoặc in + nơi chốn (at a school, in a factory); work for + công ty, tổ chức (work for a bank). Trước nơi làm việc thường cần a hoặc the: at a bank, không nói at bank. Hard đứng sau động từ: work hard là làm việc chăm chỉ.', 'Shop /ʃɑp/ tròn môi như khi suỵt; school /skul/ môi dẹt như tiếng xì. Đọc liền /s/ với /k/, đừng chèn âm "ơ" thành "sờ-cun"; cuối school là /l/, đầu lưỡi chạm lợi trên. Âm /p/ cuối shop chỉ cần khép môi. Restaurant và factory nhấn âm đầu: RES-tau-rant, FAC-to-ry.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('22b58933-dc45-5b5e-b5ea-897c64d02693', 'en-US', 'Workplaces', 'Ask Where do you work? or Where does she work? Say work at or in a place: at a school, in a factory. Say work for a company: work for a bank. Use a or the before the place. Hard comes after the verb: work hard.', 'Shop starts with /ʃ/: round your lips, like shh. School starts with /s/: flat lips, then /k/ right away, with no sound in between. End school with /l/. Say RES-tau-rant and FAC-to-ry.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
