insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('e40caa09-ff07-5787-95ab-5ffaca4a04f0', 'vi', 'cửa hàng, tiệm', array['cửa hàng', 'tiệm', 'cửa tiệm', 'hiệu']::text[], 'Người Mỹ hay gọi cửa hàng là store; shop thường dùng cho tiệm nhỏ: a small shop, a coffee shop.', '5042d146667518a1a5017644946b8650aafca44c') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
