insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('a3f3f352-16be-556d-bf9d-219b4553c6ab', 'vi', 'chăm chỉ, vất vả', array['chăm chỉ', 'vất vả', 'cật lực', 'chăm']::text[], 'Work hard là làm việc chăm chỉ. Hard còn là tính từ nghĩa là khó, cứng. Đừng nhầm với hardly: hardly work là hầu như không làm.', 'cae5970fc939e302346d8b50d4fb711b7e515c4b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('a3f3f352-16be-556d-bf9d-219b4553c6ab', 'en-US', 'with a lot of effort', '{}'::text[], 'Work hard means work with a lot of effort. Hard can also mean difficult. Hardly means almost not.', 'cae5970fc939e302346d8b50d4fb711b7e515c4b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('3c6626a2-a684-5b1c-a84a-88a7a3507f1c', '22b58933-dc45-5b5e-b5ea-897c64d02693', 1, 'Where do you work? I work at a school.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('3c6626a2-a684-5b1c-a84a-88a7a3507f1c', 'vi', 'Bạn làm việc ở đâu? Tôi làm việc ở một trường học.', array['Bạn làm việc ở đâu? Tôi làm việc ở trường học.', 'Bạn làm ở đâu? Tôi làm ở một trường học.', 'Bạn làm việc ở đâu? Tôi làm ở trường học.', 'Bạn làm việc ở đâu? Tôi làm việc tại một trường học.', 'Bạn làm ở đâu? Tôi làm ở trường.', 'Bạn làm việc ở đâu? Mình làm việc ở một trường học.']::text[], null, '04d96246ea3efe88374be84056948cf90585fadf') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('1c5caac6-f15d-5757-a7d0-8967d39c0f49', '22b58933-dc45-5b5e-b5ea-897c64d02693', 2, 'My father works in a factory.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('1c5caac6-f15d-5757-a7d0-8967d39c0f49', 'vi', 'Bố tôi làm việc trong một nhà máy.', array['Bố tôi làm việc ở nhà máy.', 'Bố tôi làm việc ở một nhà máy.', 'Bố tôi làm việc trong nhà máy.', 'Bố tôi làm ở nhà máy.', 'Bố tôi làm ở một nhà máy.', 'Ba tôi làm việc ở một nhà máy.']::text[], null, 'cc1d82b9635aa59d3933c41d29194830f3aa76e8') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('cc2b0d8e-1f45-5655-b374-ed515dc7f9ec', '22b58933-dc45-5b5e-b5ea-897c64d02693', 3, 'She works for a bank in Hanoi.', array['She works for a bank in Ha Noi.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('cc2b0d8e-1f45-5655-b374-ed515dc7f9ec', 'vi', 'Cô ấy làm việc cho một ngân hàng ở Hà Nội.', array['Cô ấy làm cho một ngân hàng ở Hà Nội.', 'Cô ấy làm việc cho ngân hàng ở Hà Nội.', 'Cô ấy làm ngân hàng ở Hà Nội.', 'Cô ấy làm việc ở một ngân hàng tại Hà Nội.', 'Cô ấy làm việc ở một ngân hàng ở Hà Nội.', 'Chị ấy làm việc cho một ngân hàng ở Hà Nội.']::text[], 'Work for + công ty, tổ chức: làm việc cho ai. Work at hoặc in + nơi chốn: làm việc ở đâu.', '86e9bf00e01164101e4324f1d264305f557f4333') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('cc2b0d8e-1f45-5655-b374-ed515dc7f9ec', 'en-US', 'She works for a bank in Hanoi.', '{}'::text[], 'Work for a company. Work at or in a place.', '86e9bf00e01164101e4324f1d264305f557f4333') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('613d6bd9-f5c2-5f6c-875f-1c994e25686e', '22b58933-dc45-5b5e-b5ea-897c64d02693', 4, 'Where does Minh work? He''s a cook at a restaurant.', array['Where does Minh work? He is a cook at a restaurant.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('613d6bd9-f5c2-5f6c-875f-1c994e25686e', 'vi', 'Minh làm việc ở đâu? Anh ấy là đầu bếp ở một nhà hàng.', array['Minh làm ở đâu? Anh ấy là đầu bếp ở một nhà hàng.', 'Minh làm việc ở đâu? Anh ấy là đầu bếp ở nhà hàng.', 'Minh làm việc ở đâu? Anh ấy làm đầu bếp ở một nhà hàng.', 'Minh làm việc ở đâu? Anh ấy là đầu bếp tại một nhà hàng.', 'Minh làm việc ở đâu? Anh ấy là đầu bếp của một nhà hàng.', 'Minh làm việc ở đâu? Cậu ấy là đầu bếp ở một nhà hàng.']::text[], null, '276121937db3ed9647373d0663bae9427e0faebc') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('fed8e726-8007-5dd5-a4bf-f3b510adf071', '22b58933-dc45-5b5e-b5ea-897c64d02693', 5, 'My parents have a small shop, and they work hard.', array['My parents have a small shop and they work hard.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('fed8e726-8007-5dd5-a4bf-f3b510adf071', 'vi', 'Bố mẹ tôi có một cửa hàng nhỏ và làm việc chăm chỉ.', array['Bố mẹ tôi có một cửa hàng nhỏ, và họ làm việc chăm chỉ.', 'Bố mẹ tôi có một cửa hàng nhỏ và làm việc vất vả.', 'Bố mẹ tôi có một cửa hàng nhỏ và làm việc rất chăm chỉ.', 'Bố mẹ tôi có một cửa hàng nhỏ và làm việc rất vất vả.', 'Bố mẹ tôi có một tiệm nhỏ và làm việc chăm chỉ.', 'Bố mẹ tôi có một cửa hàng nhỏ, và bố mẹ làm việc chăm chỉ.', 'Ba mẹ tôi có một cửa hàng nhỏ và làm việc chăm chỉ.']::text[], null, '641568e153dd0669447ae48c423951386e345bcd') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
