insert into public.lessons (id, unit_id, sort_order, kind) values ('c20e26bf-4752-5860-912f-f9f8112e90a5', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'jobs'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('c20e26bf-4752-5860-912f-f9f8112e90a5', 'vi', 'Bạn có thích việc này không', 'Phủ định động từ thường: don''t (do not) với I, you, we, they; doesn''t (does not) với he, she. Sau don''t, doesn''t động từ giữ nguyên: She doesn''t work at night (không nói doesn''t works). Đừng nói I''m not like it hay I not like it; nói I don''t like it. Also (cũng) đứng sau be và trước động từ thường: It''s also interesting. I also like it.', 'Don''t đọc /doʊnt/: âm "ô" trượt nhẹ sang "u", khác hẳn do /du/. Trong doesn''t /ˈdʌzənt/, busy /ˈbɪzi/ và easy /ˈizi/, chữ s đọc /z/ (cổ họng rung), không phải /s/. Busy đọc như "bi-zi", chữ u đọc như i. Interesting nhấn âm đầu: IN-ter-est-ing, người Mỹ hay đọc gọn /ˈɪntrəstɪŋ/. Difficult cũng nhấn âm đầu: DIF-fi-cult.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('c20e26bf-4752-5860-912f-f9f8112e90a5', 'en-US', 'Do you like it?', 'Use don''t with I, you, we and they. Use doesn''t with he and she. After them, the verb has no -s: She doesn''t work at night. Say I don''t like it, not I''m not like it. Put also after be and before other verbs: It''s also interesting. I also like it.', 'Don''t sounds different from do: /doʊnt/. In doesn''t, busy and easy, the s sounds like /z/. Busy sounds like BIZ-ee. Say IN-ter-est-ing and DIF-fi-cult, with the first part strong.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('7b7660bd-a797-5fea-82e6-3ab2cd6c970d', (select id from public.courses where slug = 'english'), 'don''t', 'contraction', '/ˈdoʊnt/', null) on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7b7660bd-a797-5fea-82e6-3ab2cd6c970d', 'vi', 'không (viết gọn của do not); đừng', array['không', 'đừng']::text[], 'Dùng với I, you, we, they: I don''t like it. Đứng đầu câu thì nghĩa là đừng.', 'b0d1d894a4aed77f598aa155982ad66f45cd947f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7b7660bd-a797-5fea-82e6-3ab2cd6c970d', 'en-US', 'the short form of do not', '{}'::text[], 'Use it with I, you, we and they: I don''t like it.', 'b0d1d894a4aed77f598aa155982ad66f45cd947f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('25caf8c9-19be-5254-bf35-6069dcb1b971', (select id from public.courses where slug = 'english'), 'doesn''t', 'contraction', '/ˈdəzənt/', null) on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('25caf8c9-19be-5254-bf35-6069dcb1b971', 'vi', 'không (viết gọn của does not, dùng với he, she)', array['không']::text[], 'Dùng với he, she, it. Động từ sau doesn''t không thêm -s: He doesn''t work.', '3090d78152a3e621d5e445916ba15d50c674da30') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('25caf8c9-19be-5254-bf35-6069dcb1b971', 'en-US', 'the short form of does not', '{}'::text[], 'Use it with he, she and it. The verb after it has no -s: He doesn''t work.', '3090d78152a3e621d5e445916ba15d50c674da30') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('9e7dafaa-c9a1-5d8f-8ebb-1996b6ac6957', (select id from public.courses where slug = 'english'), 'like', 'verb', '/ˈlaɪk/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('9e7dafaa-c9a1-5d8f-8ebb-1996b6ac6957', 'vi', 'thích', array['thích', 'ưa thích', 'mến']::text[], 'He, she dùng likes. Phủ định là don''t like, doesn''t like. I''m not like you lại có nghĩa là tôi không giống bạn.', 'c4eb7d7fea3c62a8db7078eb05a68993b456c503') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('9e7dafaa-c9a1-5d8f-8ebb-1996b6ac6957', 'en-US', 'to think that something or someone is good or nice', '{}'::text[], 'With he and she, add -s: She likes it. Say I don''t like it. I''m not like you means I am different from you.', 'c4eb7d7fea3c62a8db7078eb05a68993b456c503') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
