insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('6643261d-e60a-5739-8780-0f5aa985da55', (select id from public.courses where slug = 'english'), 'interesting', 'adjective', '/ˈɪntɝəstɪŋ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('6643261d-e60a-5739-8780-0f5aa985da55', 'vi', 'thú vị, hay', array['thú vị', 'hay', 'hấp dẫn', 'lý thú']::text[], 'Interesting tả sự việc gây hứng thú: My job is interesting. I''m interesting nghĩa là tôi là người thú vị, không phải tôi thấy hứng thú.', '68f55551796668375c528bd96b0d0fbc847bd123') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('6643261d-e60a-5739-8780-0f5aa985da55', 'en-US', 'making you want to know or learn more', '{}'::text[], 'Use interesting for the thing: My job is interesting. I''m interesting means people find you interesting.', '68f55551796668375c528bd96b0d0fbc847bd123') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('3b75cbba-0a48-5a37-871d-1d3655ddb83d', (select id from public.courses where slug = 'english'), 'also', 'adverb', '/ˈɔlsoʊ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('3b75cbba-0a48-5a37-871d-1d3655ddb83d', 'vi', 'cũng', array['cũng']::text[], 'Also đứng sau be (It''s also interesting) và trước động từ thường (I also work here). Too cũng là cũng nhưng đứng cuối câu.', '09706c418809f1f4cfda992435ca1438eddaaeed') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('3b75cbba-0a48-5a37-871d-1d3655ddb83d', 'en-US', 'too; in addition', '{}'::text[], 'Put also after be and before other verbs. Too goes at the end.', '09706c418809f1f4cfda992435ca1438eddaaeed') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('23e2eace-329e-575b-9fdb-de95f4313288', 'c20e26bf-4752-5860-912f-f9f8112e90a5', 1, 'Do you like your job? No, I don''t. It''s difficult.', array['Do you like your job? No, I do not. It is difficult.', 'Do you like your job? No, I don''t. It is difficult.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('23e2eace-329e-575b-9fdb-de95f4313288', 'vi', 'Bạn có thích công việc của mình không? Không, tôi không thích. Việc đó khó.', array['Bạn có thích công việc của bạn không? Không, tôi không thích. Việc đó khó.', 'Bạn có thích công việc của mình không? Không. Công việc đó khó.', 'Bạn có thích công việc của bạn không? Không, tôi không thích. Nó khó.', 'Bạn có thích việc của bạn không? Không, tôi không thích. Việc đó khó.', 'Bạn có thích công việc của mình không? Không, tôi không thích. Công việc khó.']::text[], 'Trả lời ngắn: No, I don''t. Không nói No, I''m not.', 'af0a93f9dd1ed3a5eb4d162d3e4d3820f7373ff7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('23e2eace-329e-575b-9fdb-de95f4313288', 'en-US', 'Do you like your job? No, I don''t. It''s difficult.', '{}'::text[], 'The short answer is No, I don''t. Do not say No, I''m not.', 'af0a93f9dd1ed3a5eb4d162d3e4d3820f7373ff7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('9f814545-3a51-5b06-867b-129510aa4bd8', 'c20e26bf-4752-5860-912f-f9f8112e90a5', 2, 'My job is easy, and it''s also interesting.', array['My job is easy, and it is also interesting.', 'My job is easy and it''s also interesting.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('9f814545-3a51-5b06-867b-129510aa4bd8', 'vi', 'Công việc của tôi dễ, và cũng thú vị.', array['Công việc của tôi dễ và cũng thú vị.', 'Công việc của tôi dễ, và nó cũng thú vị.', 'Công việc của tôi dễ, mà cũng thú vị.', 'Công việc của tôi dễ, và cũng hay.', 'Việc của tôi dễ, và cũng thú vị.', 'Công việc của tôi vừa dễ vừa thú vị.']::text[], null, 'ad561fa62b169cea97203e40c5c48b8836e1b4ed') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('ab8d8d38-160d-519b-85cf-14eb4a3ede42', 'c20e26bf-4752-5860-912f-f9f8112e90a5', 3, 'Doctors and nurses are very busy.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('ab8d8d38-160d-519b-85cf-14eb4a3ede42', 'vi', 'Bác sĩ và y tá rất bận.', array['Các bác sĩ và y tá rất bận.', 'Bác sĩ và y tá rất bận rộn.', 'Các bác sĩ và y tá rất bận rộn.', 'Bác sĩ và điều dưỡng rất bận.', 'Bác sĩ với y tá rất bận.']::text[], 'Nói chung về một nghề thì dùng số nhiều, không có the: Doctors are busy.', 'ba155fd681bd62ac935cb6e90ff7d2da2c0b7fa7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('ab8d8d38-160d-519b-85cf-14eb4a3ede42', 'en-US', 'Doctors and nurses are very busy.', '{}'::text[], 'To talk about all people in a job, use the plural without the: Doctors are busy.', 'ba155fd681bd62ac935cb6e90ff7d2da2c0b7fa7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e81f27a8-7e95-55bb-b82f-bec886f61c29', 'c20e26bf-4752-5860-912f-f9f8112e90a5', 4, 'She''s a nurse, but she doesn''t work at night.', array['She is a nurse, but she does not work at night.', 'She is a nurse, but she doesn''t work at night.', 'She''s a nurse but she doesn''t work at night.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e81f27a8-7e95-55bb-b82f-bec886f61c29', 'vi', 'Cô ấy là y tá, nhưng cô ấy không làm việc ban đêm.', array['Cô ấy là y tá nhưng không làm việc ban đêm.', 'Cô ấy là y tá, nhưng cô ấy không làm việc vào ban đêm.', 'Cô ấy là y tá, nhưng không làm đêm.', 'Cô ấy là y tá, nhưng cô ấy không làm ca đêm.', 'Cô ấy là điều dưỡng, nhưng cô ấy không làm việc ban đêm.', 'Chị ấy là y tá, nhưng chị ấy không làm việc ban đêm.']::text[], null, '8bb5ff14fae68b6bf1a73d2607cdff6c237c7abf') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('11eace4c-3276-5714-bdad-71a4885ae865', 'c20e26bf-4752-5860-912f-f9f8112e90a5', 5, 'Does your wife like her job? Yes, she does.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('11eace4c-3276-5714-bdad-71a4885ae865', 'vi', 'Vợ bạn có thích công việc của mình không? Có, cô ấy thích.', array['Vợ bạn có thích công việc của cô ấy không? Có, cô ấy thích.', 'Vợ của bạn có thích công việc của cô ấy không? Có, cô ấy thích.', 'Vợ bạn có thích công việc của cô ấy không? Có.', 'Vợ bạn có thích công việc không? Có.', 'Vợ bạn có thích việc của cô ấy không? Có.', 'Vợ bạn có thích công việc của mình không? Vâng, có.']::text[], null, 'bede3f82d398ccfa73a1ee97ae36a53f5ea219fa') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
