insert into public.lessons (id, unit_id, sort_order, kind) values ('e2005a41-4a2b-5f20-b3e4-f5836403b6f1', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'numbers-and-time'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 'vi', 'Số tới 100', 'Số tròn chục có đuôi -ty: thirty (30), forty (40), fifty (50), sixty, seventy, eighty, ninety. Chú ý chính tả: forty không có chữ u (khác four), thirty và fifty đổi chữ so với three và five, eighty chỉ có một chữ t. Số lẻ ghép số chục với số đơn vị bằng dấu gạch ngang: twenty-one (21), forty-five (45). 100 là one hundred hoặc a hundred. Sau số, hundred không thêm -s: two hundred (200).', 'Phân biệt thirteen và thirty: thirteen /ˌθɝˈtin/ nhấn âm sau, đuôi -teen kéo dài; thirty /ˈθɝti/ nhấn âm đầu, đuôi -ty ngắn và nhẹ. Người Mỹ thường đọc chữ t trong thirty, forty thành âm gần giống /d/ lướt nhanh: nghe như "thir-dy", "for-dy". Nếu người nghe chưa rõ, nói thêm từng chữ số: thirty, three zero. Hundred đọc /ˈhʌndrəd/, nhấn âm đầu: HUN-dred.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 'en-US', 'Numbers to 100', 'Tens end in -ty: thirty, forty, fifty, sixty, seventy, eighty, ninety. Forty has no u. For other numbers, use a hyphen: twenty-one (21), forty-five (45). Say 100 as one hundred or a hundred. After a number, hundred has no -s: two hundred.', 'Thirteen is strong at the end: thir-TEEN, with a long -teen. Thirty is strong at the start: THIR-ty, with a short -ty. In American English, the t in thirty and forty often sounds like a quick d. In hundred, the first part is strong: HUN-dred.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('020fb651-7ac4-5cd5-abe2-01e617348380', (select id from public.courses where slug = 'english'), 'thirty', 'number', '/ˈθɝˌdi/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('020fb651-7ac4-5cd5-abe2-01e617348380', 'vi', 'số ba mươi (30)', array['ba mươi', '30', 'số 30', 'ba chục']::text[], 'Đừng nhầm với thirteen (13). Thirty nhấn âm đầu: THIR-ty; thirteen nhấn âm sau: thir-TEEN.', 'c54450b325c13c06f573cc8750b42e81e0126528') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('020fb651-7ac4-5cd5-abe2-01e617348380', 'en-US', 'the number 30', '{}'::text[], 'Do not mix it up with thirteen (13). Say THIR-ty, but thir-TEEN.', 'c54450b325c13c06f573cc8750b42e81e0126528') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
