insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('07b26212-a7f1-5fcf-9bd2-edd842711134', 'vi', 'số bốn mươi (40)', array['bốn mươi', '40', 'số 40', 'bốn chục']::text[], 'Viết forty, không có chữ u, dù four và fourteen có chữ u.', '88ddff0da7c9c2be0e47c8aa8165964f36aae93c') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('07b26212-a7f1-5fcf-9bd2-edd842711134', 'en-US', 'the number 40', '{}'::text[], 'Forty has no u, but four and fourteen do.', '88ddff0da7c9c2be0e47c8aa8165964f36aae93c') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
