insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('30757a8d-9328-5d7f-aa56-ca26230e1590', 'vi', 'số chín mươi (90)', array['chín mươi', '90', 'số 90', 'chín chục']::text[], 'Viết ninety, giữ chữ e của nine; đừng viết ninty.', 'fd3575d2ba5cf0d709c98f2282023f3da77e7a43') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('30757a8d-9328-5d7f-aa56-ca26230e1590', 'en-US', 'the number 90', '{}'::text[], 'Ninety keeps the e from nine. Do not write ninty.', 'fd3575d2ba5cf0d709c98f2282023f3da77e7a43') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('ff6efd61-ce88-55b5-a859-b9cc6ffdaa43', (select id from public.courses where slug = 'english'), 'hundred', 'number', '/ˈhəndɹɪd/', 'A2') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('ff6efd61-ce88-55b5-a859-b9cc6ffdaa43', 'vi', 'trăm; one hundred là một trăm (100)', array['trăm', 'một trăm', '100', 'số 100']::text[], 'Sau số không thêm -s: two hundred (200). Chỉ dùng hundreds khi không nói số cụ thể: hàng trăm. Người Mỹ thường bỏ and: one hundred twenty (120).', 'e9b039adefacfd02d3163d1bfa55fdd3585eb7e7') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('ff6efd61-ce88-55b5-a859-b9cc6ffdaa43', 'en-US', 'the number 100; one hundred or a hundred', '{}'::text[], 'After a number, there is no -s: two hundred. Hundreds means many hundreds. Americans often say one hundred twenty, without and.', 'e9b039adefacfd02d3163d1bfa55fdd3585eb7e7') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('b304e929-02a4-593e-9487-2adee1888849', 'e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 1, 'Ten, twenty, thirty, forty, fifty.', array['10, 20, 30, 40, 50.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('b304e929-02a4-593e-9487-2adee1888849', 'vi', 'Mười, hai mươi, ba mươi, bốn mươi, năm mươi.', array['10, 20, 30, 40, 50.']::text[], null, 'dfb8f7daf6f275c8051e1d043cfccaa3f0b49889') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('13cc689a-7814-598f-ba83-c99fc63d48ef', 'e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 2, 'Sixty, seventy, eighty, ninety, one hundred.', array['60, 70, 80, 90, 100.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('13cc689a-7814-598f-ba83-c99fc63d48ef', 'vi', 'Sáu mươi, bảy mươi, tám mươi, chín mươi, một trăm.', array['60, 70, 80, 90, 100.']::text[], null, '87db53049895b38c311ca9ec05693a36c6e3cbd1') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('226748d6-234c-53dd-b143-85bf3e1c80b0', 'e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 3, 'Is it thirteen or thirty? Thirty.', array['Is it 13 or 30? 30.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('226748d6-234c-53dd-b143-85bf3e1c80b0', 'vi', 'Mười ba hay ba mươi? Ba mươi.', array['Là mười ba hay ba mươi? Ba mươi.', '13 hay 30? 30.', 'Số mười ba hay số ba mươi? Ba mươi.', 'Mười ba hay ba mươi vậy? Ba mươi.']::text[], 'Nghe kỹ trọng âm: thir-TEEN (13) nhấn âm sau, THIR-ty (30) nhấn âm đầu.', '2a22a3c9a299174b46290c7d3d1ef1a44edb03db') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('226748d6-234c-53dd-b143-85bf3e1c80b0', 'en-US', 'Is it thirteen or thirty? Thirty.', '{}'::text[], 'Listen for the strong part: thir-TEEN (13), THIR-ty (30).', '2a22a3c9a299174b46290c7d3d1ef1a44edb03db') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('6069831d-5878-53e5-8d9e-89eb645c8050', 'e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 4, 'I''m forty years old. And you?', array['I am forty years old. And you?', 'I''m 40 years old. And you?', 'I am 40 years old. And you?']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('6069831d-5878-53e5-8d9e-89eb645c8050', 'vi', 'Tôi bốn mươi tuổi. Còn bạn?', array['Tôi 40 tuổi. Còn bạn?', 'Tôi bốn mươi tuổi. Còn bạn thì sao?', 'Tôi 40 tuổi. Còn bạn thì sao?', 'Tôi bốn mươi tuổi rồi. Còn bạn?', 'Năm nay tôi bốn mươi tuổi. Còn bạn?']::text[], null, '6476c4ecf7f49f6660fd8dc3bf2ac54118d3a8c5') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('c99d945a-9347-5bc8-9dfc-88252d42730e', 'e2005a41-4a2b-5f20-b3e4-f5836403b6f1', 5, 'Our school has a hundred students.', array['Our school has 100 students.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c99d945a-9347-5bc8-9dfc-88252d42730e', 'vi', 'Trường chúng tôi có một trăm học sinh.', array['Trường của chúng tôi có một trăm học sinh.', 'Trường chúng tôi có 100 học sinh.', 'Trường tôi có một trăm học sinh.', 'Trường chúng tôi có một trăm sinh viên.', 'Trường của chúng tôi có 100 học sinh.']::text[], 'A hundred và one hundred đều là một trăm.', '7f86445639b386cd24157f945a643a5999017f5a') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c99d945a-9347-5bc8-9dfc-88252d42730e', 'en-US', 'Our school has a hundred students.', '{}'::text[], 'A hundred and one hundred mean the same.', '7f86445639b386cd24157f945a643a5999017f5a') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
