insert into public.lessons (id, unit_id, sort_order, kind) values ('1f03f87d-b8d3-5af4-bbe5-122fca4083f3', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'numbers-and-time'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 'vi', 'Mấy giờ rồi', 'Hỏi giờ: What time is it? Trả lời đầy đủ bằng It''s: It''s seven o''clock. Tiếng Anh cần chủ ngữ it, khác tiếng Việt chỉ cần nói "bảy giờ". O''clock chỉ dùng với giờ chẵn. Giờ lẻ có hai cách. Cách thứ nhất, nói giờ trước, phút sau: eight thirty (8:30); người Mỹ hay nói kiểu này nhất. Cách thứ hai, nói phút trước: half past eight (8 giờ rưỡi), a quarter past eight (8:15), a quarter to nine (8:45, tức 9 giờ kém 15). Chú ý: half past eight là 8 giờ rưỡi, không phải 7 giờ rưỡi.', 'O''clock đọc /əˈklɑk/: chữ o đọc rất nhẹ /ə/, nhấn vào clock. Half đọc /hæf/: chữ l câm. Minute đọc /ˈmɪnət/: MIN-ut, đừng đọc thành "mai-nút". Quarter đọc /ˈkwɔrtɚ/; người Mỹ thường đọc chữ t thành âm gần giống /d/ nhẹ: "quar-der". Time đọc /taɪm/: ngậm môi ở âm /m/ cuối.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 'en-US', 'What time is it?', 'Ask: What time is it? Answer with It''s: It''s seven o''clock. Use o''clock only for full hours. You can say the hour, then the minutes: eight thirty (8:30). Americans say it this way most. Or say the minutes first: half past eight (8:30), a quarter past eight (8:15), a quarter to nine (8:45).', 'In o''clock, the o is very weak: /əˈklɑk/. In half, do not say the l. Minute is MIN-ut. In American English, the t in quarter often sounds like a quick d. Close your lips at the end of time.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('f76a5215-55a6-518d-92e8-188335fce13f', (select id from public.courses where slug = 'english'), 'time', 'noun', '/ˈtaɪm/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('f76a5215-55a6-518d-92e8-188335fce13f', 'vi', 'thời gian; giờ (trên đồng hồ)', array['thời gian', 'giờ', 'thì giờ']::text[], 'What time is it? là mấy giờ rồi. Khi nghĩa là thời gian nói chung, time thường không đi với a: I have time.', '714eea0f4c980736bde0065fe73f573487f08e3a') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('f76a5215-55a6-518d-92e8-188335fce13f', 'en-US', 'what we measure in hours and minutes; the hour on a clock', '{}'::text[], 'What time is it? asks about the clock. When it means time in general, we usually do not use a: I have time.', '714eea0f4c980736bde0065fe73f573487f08e3a') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('f13cb940-dbf4-553a-b0b2-97ba56cc131a', (select id from public.courses where slug = 'english'), 'o''clock', 'adverb', '/əˈklɑk/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('f13cb940-dbf4-553a-b0b2-97ba56cc131a', 'vi', 'giờ đúng, giờ chẵn (đứng sau số giờ)', array['giờ', 'giờ đúng', 'giờ chẵn']::text[], 'Chỉ dùng với giờ chẵn: seven o''clock. Không nói seven thirty o''clock.', '22286fa349f134bdccd0d1c3aeca1d143538dbb3') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('f13cb940-dbf4-553a-b0b2-97ba56cc131a', 'en-US', 'used after a number to say an exact hour, as in seven o''clock', '{}'::text[], 'Use it only for full hours: seven o''clock, not seven thirty o''clock.', '22286fa349f134bdccd0d1c3aeca1d143538dbb3') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('003bb096-1cd6-5a18-a27f-e210fad920ce', (select id from public.courses where slug = 'english'), 'half', 'noun', '/ˈhæf/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('003bb096-1cd6-5a18-a27f-e210fad920ce', 'vi', 'một nửa; half past là rưỡi', array['nửa', 'một nửa', 'rưỡi']::text[], 'Half past eight là 8 giờ rưỡi (8:30).', '6dbdd59ab542c91f19905b4d8672b5320dcba285') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('003bb096-1cd6-5a18-a27f-e210fad920ce', 'en-US', 'one of two equal parts; half past eight is 8:30', '{}'::text[], 'Half past eight is 8:30.', '6dbdd59ab542c91f19905b4d8672b5320dcba285') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('4e3746a4-ca2c-55f6-b9a6-e60a30722e89', (select id from public.courses where slug = 'english'), 'past', 'preposition', '/ˈpæst/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('4e3746a4-ca2c-55f6-b9a6-e60a30722e89', 'vi', 'quá, hơn (khi nói giờ)', array['quá', 'hơn', 'qua']::text[], 'Ten past eight là 8 giờ 10 (tám giờ hơn mười phút). Người Mỹ cũng hay nói after: ten after eight.', 'dc52f279269d00ddcc22b2e6bb47a812c140dfdc') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('4e3746a4-ca2c-55f6-b9a6-e60a30722e89', 'en-US', 'after the hour, when you say the time', '{}'::text[], 'Ten past eight is 8:10. Americans also say ten after eight.', 'dc52f279269d00ddcc22b2e6bb47a812c140dfdc') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('b9443719-901f-5034-8c1e-d482c8b88f25', (select id from public.courses where slug = 'english'), 'quarter', 'noun', '/ˈkwɔɹtɝ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('b9443719-901f-5034-8c1e-d482c8b88f25', 'vi', 'mười lăm phút; một phần tư', array['mười lăm phút', '15 phút', 'một phần tư', 'một khắc']::text[], 'A quarter past eight là 8:15; a quarter to nine là 8:45 (9 giờ kém 15). Ở Mỹ, quarter còn là đồng 25 xu.', '7fa1f94325c1f93ccb98d699eacb2bfd7d300dc2') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('b9443719-901f-5034-8c1e-d482c8b88f25', 'en-US', 'fifteen minutes; one of four equal parts', '{}'::text[], 'A quarter past eight is 8:15. A quarter to nine is 8:45. In America, a quarter is also a 25-cent coin.', '7fa1f94325c1f93ccb98d699eacb2bfd7d300dc2') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('0d893748-6b51-5e0f-a0f2-cf7355c46e68', (select id from public.courses where slug = 'english'), 'minute', 'noun', '/ˈmɪnət/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0d893748-6b51-5e0f-a0f2-cf7355c46e68', 'vi', 'phút', array['phút', 'một phút']::text[], 'Đọc /ˈmɪnət/: MIN-ut, nhấn vào âm đầu; chữ u thứ hai đọc rất nhẹ.', '04987fcab72ade3a87a64267b02a2ad9f8f22484') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0d893748-6b51-5e0f-a0f2-cf7355c46e68', 'en-US', 'sixty seconds; there are sixty in an hour', '{}'::text[], 'Say MIN-ut. The first part is strong.', '04987fcab72ade3a87a64267b02a2ad9f8f22484') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('1a2f5121-446e-59b8-990a-3ea687cb123e', '1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 1, 'Excuse me, what time is it?', array['Excuse me. What time is it?']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('1a2f5121-446e-59b8-990a-3ea687cb123e', 'vi', 'Xin lỗi, mấy giờ rồi ạ?', array['Xin lỗi, bây giờ là mấy giờ?', 'Xin lỗi, mấy giờ rồi?', 'Xin lỗi, cho hỏi mấy giờ rồi ạ?', 'Xin lỗi, bây giờ là mấy giờ ạ?', 'Xin lỗi, bây giờ mấy giờ rồi?']::text[], null, 'efc6ae7a5412993de63fb3302471dfea82d794b9') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('a7edf1a1-13df-58e2-acf1-59a087527087', '1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 2, 'It''s seven o''clock.', array['It is seven o''clock.', 'It''s 7 o''clock.', 'It is 7 o''clock.', 'It''s 7:00.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a7edf1a1-13df-58e2-acf1-59a087527087', 'vi', 'Bây giờ là bảy giờ.', array['Bảy giờ rồi.', 'Bảy giờ đúng.', 'Bây giờ là bảy giờ đúng.', 'Bây giờ là 7 giờ.', '7 giờ rồi.', '7 giờ đúng.']::text[], null, '913874193cb9e9b2a84a35255c86ab8438809fad') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('c2991eb1-837b-553f-bde0-64ed6dc61ba7', '1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 3, 'It''s half past eight. It''s eight thirty.', array['It is half past eight. It is eight thirty.', 'It''s half past 8. It''s 8:30.', 'It is half past 8. It is 8:30.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c2991eb1-837b-553f-bde0-64ed6dc61ba7', 'vi', 'Bây giờ là tám giờ rưỡi. Tám giờ ba mươi.', array['Tám giờ rưỡi. Tám giờ ba mươi.', 'Tám giờ rưỡi rồi. Tám giờ ba mươi phút.', 'Bây giờ là 8 giờ rưỡi. 8 giờ 30.', '8 giờ rưỡi. 8 giờ 30.']::text[], 'Hai cách nói cùng một giờ (8:30). Người Mỹ hay nói eight thirty hơn.', '7fe0c856eba65ef4a7f77231433f09a93c74b6f6') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c2991eb1-837b-553f-bde0-64ed6dc61ba7', 'en-US', 'It''s half past eight. It''s eight thirty.', '{}'::text[], 'Two ways to say 8:30. Americans say eight thirty more often.', '7fe0c856eba65ef4a7f77231433f09a93c74b6f6') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('ac6b7536-60c4-5472-a253-89d29a45beb6', '1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 4, 'It''s a quarter to nine.', array['It is a quarter to nine.', 'It''s a quarter to 9.', 'It is a quarter to 9.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('ac6b7536-60c4-5472-a253-89d29a45beb6', 'vi', 'Bây giờ là chín giờ kém mười lăm.', array['Chín giờ kém mười lăm.', 'Chín giờ kém mười lăm phút.', 'Bây giờ là 9 giờ kém 15.', '9 giờ kém 15.', 'Bây giờ là tám giờ bốn mươi lăm.', '8 giờ 45.']::text[], 'A quarter to nine là 8:45 (còn mười lăm phút nữa là chín giờ), không phải 9:15.', '31530594a22c8c83345f1804b4dc0bbd03c0d991') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('ac6b7536-60c4-5472-a253-89d29a45beb6', 'en-US', 'It''s a quarter to nine.', '{}'::text[], 'A quarter to nine is 8:45, not 9:15.', '31530594a22c8c83345f1804b4dc0bbd03c0d991') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e4c8d255-6d9f-5eea-8618-b02d381b3d90', '1f03f87d-b8d3-5af4-bbe5-122fca4083f3', 5, 'See you in ten minutes.', array['See you in 10 minutes.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e4c8d255-6d9f-5eea-8618-b02d381b3d90', 'vi', 'Mười phút nữa gặp nhé.', array['Hẹn gặp bạn sau mười phút nữa.', 'Mười phút nữa gặp lại nhé.', 'Hẹn gặp lại sau 10 phút nữa.', '10 phút nữa gặp nhé.', 'Gặp bạn sau mười phút nữa nhé.', 'Mười phút nữa gặp lại.']::text[], 'In + khoảng thời gian nghĩa là sau ... nữa, tính từ bây giờ: in ten minutes là mười phút nữa.', '84c09ea56d5018399ce38dff9a87318dad8eb860') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e4c8d255-6d9f-5eea-8618-b02d381b3d90', 'en-US', 'See you in ten minutes.', '{}'::text[], 'In ten minutes means ten minutes from now.', '84c09ea56d5018399ce38dff9a87318dad8eb860') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
