insert into public.lessons (id, unit_id, sort_order, kind) values ('dca82a3a-abaf-53fa-a2fb-dabc42904d3e', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'numbers-and-time'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('dca82a3a-abaf-53fa-a2fb-dabc42904d3e', 'vi', 'Sớm và muộn', 'Nói làm việc gì lúc mấy giờ dùng at + giờ: I get up at six. Không dùng in hay on trước giờ. Get up là thức dậy, ra khỏi giường. Go to work là đi làm: không có the trước work. Hỏi giờ làm việc gì: What time do you + động từ? What time do you go to work? Không bỏ do. Hour bắt đầu bằng âm nguyên âm nên dùng an: an hour.', 'Hour đọc /ˈaʊɚ/: chữ h câm, đọc giống our. Early đọc /ˈɝli/: mở đầu bằng âm "ơ" cong lưỡi, không có âm e. Late /leɪt/ và get /ɡɛt/ có âm /t/ cuối: người Mỹ có thể không bật hơi nhưng vẫn chặn hơi ở cuối, đừng bỏ hẳn. Get up đọc nối liền; chữ t nằm giữa hai nguyên âm nên nghe như /d/ nhẹ: "ge-dup".') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('dca82a3a-abaf-53fa-a2fb-dabc42904d3e', 'en-US', 'Early and late', 'Use at with clock times: I get up at six. Do not use in or on. Get up means leave your bed. Say go to work, with no the. Ask: What time do you go to work? Do not leave out do. Say an hour, because hour starts with a vowel sound.', 'In hour, the h is silent: it sounds like our. Early starts with the sound in her, not e. Do not drop the t at the end of late and get. Say get up as one word; the t sounds like a quick d.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('c05ef1b4-c34a-5c1f-ae9e-c34027ab2067', (select id from public.courses where slug = 'english'), 'hour', 'noun', '/ˈaʊɝ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('c05ef1b4-c34a-5c1f-ae9e-c34027ab2067', 'vi', 'giờ, tiếng (60 phút)', array['giờ', 'tiếng', 'tiếng đồng hồ', 'một giờ', 'một tiếng']::text[], 'Chữ h câm nên dùng an: an hour (một tiếng).', '52ab86a87214a453d9f82538264f190854915247') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('c05ef1b4-c34a-5c1f-ae9e-c34027ab2067', 'en-US', 'sixty minutes', '{}'::text[], 'The h is silent, so say an hour.', '52ab86a87214a453d9f82538264f190854915247') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
