insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('fe0eeccf-09b5-50c3-ad52-11271e3b9121', 'vi', 'bây giờ', array['bây giờ', 'giờ', 'lúc này', 'hiện giờ']::text[], null, 'c9bc849a968f2432684aca234f30596c5a91654f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('fe0eeccf-09b5-50c3-ad52-11271e3b9121', 'en-US', 'at this time', '{}'::text[], null, 'c9bc849a968f2432684aca234f30596c5a91654f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('0be054f9-1e29-5f26-a6bf-26d62302cd7d', (select id from public.courses where slug = 'english'), 'early', 'adverb', '/ˈɝli/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0be054f9-1e29-5f26-a6bf-26d62302cd7d', 'vi', 'sớm', array['sớm']::text[], 'I get up early là tôi dậy sớm. You''re early là bạn đến sớm.', '818743b967a1fdbff52bbeef8fb9d62fb9b4e7bb') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0be054f9-1e29-5f26-a6bf-26d62302cd7d', 'en-US', 'before the usual or planned time', '{}'::text[], 'I get up early. You''re early means you came before the time.', '818743b967a1fdbff52bbeef8fb9d62fb9b4e7bb') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('e08a038c-c913-5f82-a67e-6de97adc70ba', (select id from public.courses where slug = 'english'), 'late', 'adjective', '/ˈleɪt/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('e08a038c-c913-5f82-a67e-6de97adc70ba', 'vi', 'muộn, trễ', array['muộn', 'trễ', 'đến muộn', 'bị muộn']::text[], 'I''m late là tôi đến muộn, tôi bị trễ. It''s late là đã muộn rồi (đã khuya).', '5d6200f8cf98af475edcac2c97f966ad156ed51f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('e08a038c-c913-5f82-a67e-6de97adc70ba', 'en-US', 'after the usual or planned time', '{}'::text[], 'I''m late means I come after the right time. It''s late means the time is late, often at night.', '5d6200f8cf98af475edcac2c97f966ad156ed51f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('896c452a-c3e8-56e5-ae57-e41a6a6cabdc', (select id from public.courses where slug = 'english'), 'get', 'verb', '/ˈɡɛt/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('896c452a-c3e8-56e5-ae57-e41a6a6cabdc', 'vi', 'lấy, nhận được; get up là thức dậy', array['lấy', 'nhận', 'nhận được', 'có được']::text[], 'Get up là thức dậy, ra khỏi giường. Với he, she dùng gets: She gets up at six.', '783923e57ba5e8f1044632c31fd806ee24814bb5') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('896c452a-c3e8-56e5-ae57-e41a6a6cabdc', 'en-US', 'to have or take something; get up means leave your bed', '{}'::text[], 'Get up means leave your bed. Use gets with he and she: She gets up at six.', '783923e57ba5e8f1044632c31fd806ee24814bb5') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
