insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('978a79d2-5349-5a74-961c-4dd7568326ce', 'vi', 'lên, lên trên; get up là thức dậy', array['lên', 'lên trên']::text[], null, '7c0a25c06ea30bae50e39a37a5997e31a1a96e20') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
