insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('0ab1fc4e-a56b-5023-b2c3-7382c6823b8a', (select id from public.courses where slug = 'english'), 'go', 'verb', '/ˈɡoʊ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0ab1fc4e-a56b-5023-b2c3-7382c6823b8a', 'vi', 'đi', array['đi', 'đi đến', 'đi tới']::text[], 'Go to work (đi làm), go to school (đi học): không có the. Với he, she dùng goes.', '1ec558a60b5dda24597816c924776716018caf8b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0ab1fc4e-a56b-5023-b2c3-7382c6823b8a', 'en-US', 'to move to another place', '{}'::text[], 'Say go to work and go to school, with no the. Use goes with he and she.', '1ec558a60b5dda24597816c924776716018caf8b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5dcb4020-50cc-53c2-9696-5d5f7242598a', 'dca82a3a-abaf-53fa-a2fb-dabc42904d3e', 1, 'I get up early, at five thirty.', array['I get up early, at 5:30.', 'I get up early at five thirty.', 'I get up early at 5:30.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5dcb4020-50cc-53c2-9696-5d5f7242598a', 'vi', 'Tôi dậy sớm, lúc năm giờ rưỡi.', array['Tôi thức dậy sớm, lúc năm giờ rưỡi.', 'Tôi dậy sớm, lúc 5 giờ 30.', 'Tôi dậy sớm lúc năm rưỡi.', 'Tôi dậy sớm, lúc 5 giờ rưỡi.', 'Tôi dậy sớm, vào lúc năm giờ ba mươi.']::text[], null, '02bebf82d5e9401a5e0b9112758ea338a6fb886d') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('f8176bf4-982b-5964-a4ab-91d19a1168be', 'dca82a3a-abaf-53fa-a2fb-dabc42904d3e', 2, 'It''s nine now. I''m late!', array['It is nine now. I am late!', 'It''s 9 now. I''m late!', 'It is 9 now. I am late!']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('f8176bf4-982b-5964-a4ab-91d19a1168be', 'vi', 'Chín giờ rồi. Tôi muộn mất rồi!', array['Bây giờ là chín giờ. Tôi bị muộn rồi!', 'Chín giờ rồi. Tôi muộn rồi!', 'Chín giờ rồi. Tôi trễ mất rồi!', '9 giờ rồi. Tôi trễ rồi!', 'Bây giờ là 9 giờ. Tôi muộn rồi!']::text[], null, 'efed72db3eaa76fda33f1e528813ee73ead99baf') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
