insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('068163e9-bf7e-53ef-befb-4d2a812ba709', 'vi', 'Bạn đi làm lúc mấy giờ?', array['Mấy giờ bạn đi làm?', 'Bạn đi làm lúc mấy giờ vậy?', 'Anh đi làm lúc mấy giờ?', 'Chị đi làm lúc mấy giờ?', 'Bạn đi làm mấy giờ?']::text[], 'Câu hỏi có động từ thường cần do: What time do you go to work? Không nói What time you go to work?', 'ee51d2d88c73bbfbfec6271d600b26d9296b9f55') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('068163e9-bf7e-53ef-befb-4d2a812ba709', 'en-US', 'What time do you go to work?', '{}'::text[], 'Use do in the question: What time do you go to work?', 'ee51d2d88c73bbfbfec6271d600b26d9296b9f55') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
