insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('6430e6cd-42a7-5e55-80d0-49d26c45c305', 'vi', 'Tôi đi làm lúc tám giờ kém mười lăm.', array['Tôi đi làm lúc 8 giờ kém 15.', 'Tôi đi làm lúc tám giờ kém mười lăm phút.', 'Tôi đi làm lúc bảy giờ bốn mươi lăm.', 'Tôi đi làm lúc 7 giờ 45.']::text[], null, '24d0cc0e8d6d453b29814f0b75d7ad21372551a1') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
