insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5492ba4e-073c-5d0f-8b2b-548bc35ea417', 'vi', 'Bố mẹ tôi sống cách đây một tiếng.', array['Bố mẹ tôi ở cách đây một tiếng.', 'Ba mẹ tôi sống cách đây một tiếng.', 'Bố mẹ tôi sống cách đây một tiếng đồng hồ.', 'Bố mẹ tôi sống cách đây một giờ đi đường.', 'Cha mẹ tôi sống cách đây một tiếng.', 'Nhà bố mẹ tôi cách đây một tiếng.']::text[], 'An hour from here là cách đây một tiếng đi đường. Dùng an vì chữ h trong hour câm.', '973ba6e920a625f0ab42a5ce91f91e8e8b81c309') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5492ba4e-073c-5d0f-8b2b-548bc35ea417', 'en-US', 'My parents live an hour from here.', '{}'::text[], 'An hour from here means it takes an hour to go there. Use an because the h in hour is silent.', '973ba6e920a625f0ab42a5ce91f91e8e8b81c309') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
