insert into public.lessons (id, unit_id, sort_order, kind) values ('a8039a66-58ca-5f32-8d35-f8407fc1807c', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'numbers-and-time'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('a8039a66-58ca-5f32-8d35-f8407fc1807c', 'vi', 'Giờ mở cửa, giờ học', 'Nói lịch, giờ mở cửa, giờ học dùng thì hiện tại đơn. Với he, she, it hoặc một danh từ số ít (the bank, my class), động từ thêm -s: The bank opens at nine. My class starts at seven thirty. Động từ tận cùng bằng -sh, -ss, -o thêm -es: finishes, goes. Với I, you, we, they thì giữ nguyên: I finish at five. Until là đến, cho đến: I''m at the office until six. Every đi với danh từ số ít: every morning, không nói every mornings.', 'Close (động từ, đóng) đọc /kloʊz/ với âm /z/ cuối; close (tính từ, gần) đọc /kloʊs/. Đuôi -s đọc /z/ sau âm hữu thanh (opens), /s/ sau âm vô thanh (starts); sau âm /s/, /z/, /ʃ/ thì thêm một âm tiết /ɪz/: CLO-ses, FIN-i-shes. Every đọc hai âm tiết /ˈɛvri/: EV-ry. Until nhấn âm sau: un-TIL.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('a8039a66-58ca-5f32-8d35-f8407fc1807c', 'en-US', 'Opening times and classes', 'Use the present simple for schedules. With he, she, it or one thing (the bank, my class), add -s to the verb: The bank opens at nine. Add -es after -sh, -ss and -o: finishes, goes. With I, you, we and they, do not add -s. Until means up to a time. Every comes before a singular noun: every morning.', 'The verb close ends in /z/: /kloʊz/. The -s ending sounds like /z/ in opens and /s/ in starts. Closes and finishes get an extra part: CLO-ses, FIN-i-shes. Say every in two parts: EV-ry. In until, the second part is strong: un-TIL.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('44f21483-e538-5256-a0d1-16221b7663e9', (select id from public.courses where slug = 'english'), 'start', 'verb', '/ˈstɑɹt/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('44f21483-e538-5256-a0d1-16221b7663e9', 'vi', 'bắt đầu', array['bắt đầu']::text[], 'Với he, she, it dùng starts: The class starts at seven.', '2b020927d3c6eb407223a1baa3d6ce3597a3f88d') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('44f21483-e538-5256-a0d1-16221b7663e9', 'en-US', 'to begin', '{}'::text[], 'Use starts with he, she and it: The class starts at seven.', '2b020927d3c6eb407223a1baa3d6ce3597a3f88d') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('9eafe122-d67a-5097-879d-6dd581c4a4c9', (select id from public.courses where slug = 'english'), 'finish', 'verb', '/ˈfɪnɪʃ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('9eafe122-d67a-5097-879d-6dd581c4a4c9', 'vi', 'kết thúc, xong, làm xong', array['kết thúc', 'xong', 'làm xong', 'hoàn thành']::text[], 'Finish work là tan làm. Với he, she, it thêm -es: finishes.', '2cce4a92f41fe3d55a72c27b922c093bdd0a4267') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('9eafe122-d67a-5097-879d-6dd581c4a4c9', 'en-US', 'to end; to do the last part of something', '{}'::text[], 'Finish work means stop working for the day. With he, she and it, say finishes.', '2cce4a92f41fe3d55a72c27b922c093bdd0a4267') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('0689d913-80fb-5432-b0f9-0d7aaa52038f', (select id from public.courses where slug = 'english'), 'open', 'verb', '/ˈoʊpən/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0689d913-80fb-5432-b0f9-0d7aaa52038f', 'vi', 'mở, mở cửa', array['mở', 'mở cửa']::text[], 'Động từ: The bank opens at nine (ngân hàng mở cửa lúc chín giờ). Open còn là tính từ: The bank is open (ngân hàng đang mở cửa).', '5fc7e38bffe00ca46add89145464a2eaf759d5c2') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0689d913-80fb-5432-b0f9-0d7aaa52038f', 'en-US', 'to begin business for the day; to move a door so people can go in', '{}'::text[], 'Verb: The bank opens at nine. Open is also an adjective: The bank is open.', '5fc7e38bffe00ca46add89145464a2eaf759d5c2') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('8d0ccac4-2736-533b-bed9-b552818c47a3', (select id from public.courses where slug = 'english'), 'close', 'verb', '/ˈkloʊz/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('8d0ccac4-2736-533b-bed9-b552818c47a3', 'vi', 'đóng, đóng cửa', array['đóng', 'đóng cửa']::text[], 'Động từ close đọc /kloʊz/. Tính từ close (gần) viết giống nhưng đọc /kloʊs/.', 'da38860cb875cb64092e402d80d9fe29c4865b18') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('8d0ccac4-2736-533b-bed9-b552818c47a3', 'en-US', 'to stop business for the day; to move a door so it is not open', '{}'::text[], 'The verb close ends in a z sound. The adjective close (near) ends in an s sound.', 'da38860cb875cb64092e402d80d9fe29c4865b18') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('4e663e4d-2247-5f37-9c31-d863aa0cf964', (select id from public.courses where slug = 'english'), 'class', 'noun', '/ˈklæs/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('4e663e4d-2247-5f37-9c31-d863aa0cf964', 'vi', 'lớp học; buổi học', array['lớp', 'lớp học', 'buổi học', 'tiết học', 'giờ học']::text[], 'Số nhiều là classes. Class vừa là lớp học, vừa là buổi học: My class starts at seven.', '8d767bf5b72373d12f0efd4406677e9ed076f592') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('4e663e4d-2247-5f37-9c31-d863aa0cf964', 'en-US', 'a group of students, or a time when they learn together', '{}'::text[], 'The plural is classes. Class can mean a group of students or a lesson time.', '8d767bf5b72373d12f0efd4406677e9ed076f592') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('93277ac5-5281-5f22-a349-2a51325d038a', (select id from public.courses where slug = 'english'), 'until', 'preposition', '/ənˈtɪl/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('93277ac5-5281-5f22-a349-2a51325d038a', 'vi', 'đến, cho đến (một thời điểm)', array['đến', 'cho đến', 'tới', 'cho tới']::text[], 'Từ ... đến ...: from eight until five, hoặc from eight to five.', 'b310f4d4d89b8570184b9777ad7d90fc1df20457') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('93277ac5-5281-5f22-a349-2a51325d038a', 'en-US', 'up to a certain time', '{}'::text[], 'From eight until five, or from eight to five.', 'b310f4d4d89b8570184b9777ad7d90fc1df20457') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('dd6f7cdc-8bd1-5818-b1e7-fb2f644a9646', (select id from public.courses where slug = 'english'), 'every', 'determiner', '/ˈɛvɹi/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('dd6f7cdc-8bd1-5818-b1e7-fb2f644a9646', 'vi', 'mỗi, mọi, hằng', array['mỗi', 'mọi', 'hằng', 'hàng']::text[], 'Every + danh từ số ít: every morning (mỗi sáng, sáng nào cũng), không nói every mornings.', '5873f666d03fb3fb39d0db9c71b5e1f769334088') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('dd6f7cdc-8bd1-5818-b1e7-fb2f644a9646', 'en-US', 'each one of a group, with no exception', '{}'::text[], 'Use a singular noun after every: every morning, not every mornings.', '5873f666d03fb3fb39d0db9c71b5e1f769334088') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('a9c4b7fe-1238-5582-9f69-31bf2bd8bdb3', 'a8039a66-58ca-5f32-8d35-f8407fc1807c', 1, 'The bank opens at nine and closes at five.', array['The bank opens at 9 and closes at 5.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a9c4b7fe-1238-5582-9f69-31bf2bd8bdb3', 'vi', 'Ngân hàng mở cửa lúc chín giờ và đóng cửa lúc năm giờ.', array['Ngân hàng mở cửa lúc 9 giờ và đóng cửa lúc 5 giờ.', 'Ngân hàng mở cửa lúc chín giờ, đóng cửa lúc năm giờ.', 'Ngân hàng mở lúc chín giờ và đóng lúc năm giờ.', 'Ngân hàng mở cửa từ chín giờ đến năm giờ.']::text[], 'The bank là một thứ (số ít) nên opens, closes có -s.', '738d859e49df915183aa257d9af07aa28f8c4cac') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a9c4b7fe-1238-5582-9f69-31bf2bd8bdb3', 'en-US', 'The bank opens at nine and closes at five.', '{}'::text[], 'The bank is one thing, so we say opens and closes.', '738d859e49df915183aa257d9af07aa28f8c4cac') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5a9abafa-4737-5640-ba68-03d0f8e1722b', 'a8039a66-58ca-5f32-8d35-f8407fc1807c', 2, 'My class starts at seven thirty.', array['My class starts at 7:30.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5a9abafa-4737-5640-ba68-03d0f8e1722b', 'vi', 'Lớp học của tôi bắt đầu lúc bảy giờ rưỡi.', array['Lớp của tôi bắt đầu lúc bảy giờ rưỡi.', 'Lớp tôi bắt đầu lúc 7 giờ 30.', 'Lớp học của tôi bắt đầu lúc 7 giờ rưỡi.', 'Buổi học của tôi bắt đầu lúc bảy giờ rưỡi.', 'Lớp của tôi bắt đầu lúc bảy giờ ba mươi.', 'Lớp tôi vào học lúc bảy rưỡi.']::text[], null, '83242199335cf2076cf2d0058c895c1b1e0a5331') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('9f87dfe5-6807-5ba4-9c66-3e0ceb7ce524', 'a8039a66-58ca-5f32-8d35-f8407fc1807c', 3, 'What time do you finish work?', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('9f87dfe5-6807-5ba4-9c66-3e0ceb7ce524', 'vi', 'Bạn tan làm lúc mấy giờ?', array['Mấy giờ bạn tan làm?', 'Bạn làm xong lúc mấy giờ?', 'Mấy giờ bạn xong việc?', 'Bạn hết giờ làm lúc mấy giờ?', 'Anh tan làm lúc mấy giờ?', 'Chị tan làm lúc mấy giờ?']::text[], null, 'e7f580c42c8f8f387252fb8760f32da5e0ea041b') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e3a43159-5a5e-58ba-84cb-6dc9c3b8e712', 'a8039a66-58ca-5f32-8d35-f8407fc1807c', 4, 'I''m at the office until six.', array['I am at the office until six.', 'I''m at the office until 6.', 'I am at the office until 6.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e3a43159-5a5e-58ba-84cb-6dc9c3b8e712', 'vi', 'Tôi ở văn phòng đến sáu giờ.', array['Tôi ở văn phòng cho đến sáu giờ.', 'Tôi ở văn phòng tới 6 giờ.', 'Tôi ở văn phòng đến 6 giờ.', 'Tôi ở cơ quan đến sáu giờ.', 'Tôi ở công ty đến sáu giờ.']::text[], null, 'ff74cf8c7b75c246480316ef4d0aa5a588efe17e') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('d2e898c5-5ce1-5458-b94a-5319ce914fb4', 'a8039a66-58ca-5f32-8d35-f8407fc1807c', 5, 'I get up at six every morning.', array['I get up at 6 every morning.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('d2e898c5-5ce1-5458-b94a-5319ce914fb4', 'vi', 'Sáng nào tôi cũng dậy lúc sáu giờ.', array['Tôi dậy lúc sáu giờ mỗi sáng.', 'Mỗi sáng tôi dậy lúc sáu giờ.', 'Hằng sáng tôi thức dậy lúc 6 giờ.', 'Sáng nào tôi cũng thức dậy lúc 6 giờ.', 'Tôi thức dậy lúc sáu giờ mỗi sáng.', 'Hằng sáng tôi dậy lúc sáu giờ.']::text[], null, 'c993c7cb8f06e0502a14bcfbf57200bfdc1d5c4d') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
