insert into public.lessons (id, unit_id, sort_order, kind) values ('be33fc6b-26f1-5729-b135-05c856f509f4', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'days-and-months'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('be33fc6b-26f1-5729-b135-05c856f509f4', 'vi', 'Các ngày trong tuần', 'Thứ trong tuần luôn viết hoa chữ cái đầu: Monday, không viết monday. Trước thứ dùng on: on Monday (vào thứ Hai), không nói in Monday. Thêm -s để nói việc lặp lại hằng tuần: on Mondays là thứ Hai nào cũng vậy. Hỏi thứ: What day is it? (Hôm nay thứ mấy?)', 'Các thứ trong tuần đều nhấn vào âm đầu, đuôi -day đọc nhẹ /deɪ/ (nhiều người Mỹ đọc lướt thành /di/): MON-day, FRI-day. Wednesday chỉ có hai âm tiết /ˈwɛnzdeɪ/ (WENZ-day): chữ d đầu và chữ e thứ hai không đọc. Trong Tuesday, Wednesday, Thursday, chữ s đọc /z/. Giọng Mỹ đọc Tuesday là /ˈtuzdeɪ/. Thursday bắt đầu bằng /θ/: đặt đầu lưỡi giữa hai hàm răng rồi thổi hơi, đừng đọc thành /t/ hay /s/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('be33fc6b-26f1-5729-b135-05c856f509f4', 'en-US', 'Days of the week', 'Days of the week always start with a capital letter: Monday. Use on before a day: on Monday. Add -s for something that happens every week: on Mondays. To ask the day, say: What day is it?', 'All weekdays have stress on the first part: MON-day, FRI-day. Wednesday has only two parts: WENZ-day. Do not say the first d. In Tuesday, Wednesday and Thursday, the s sounds like /z/. Thursday starts with /θ/: put your tongue between your teeth and blow.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('0202a18e-298c-5745-a66e-fece8600ed8c', (select id from public.courses where slug = 'english'), 'day', 'noun', '/ˈdeɪ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0202a18e-298c-5745-a66e-fece8600ed8c', 'vi', 'ngày', array['ngày', 'một ngày', 'hôm']::text[], 'What day is it? là hỏi thứ mấy (Monday, Tuesday...), không phải hỏi ngày mấy.', 'a2620cbc10f5198dd03e3f5a1569eb5dcf9a6a87') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0202a18e-298c-5745-a66e-fece8600ed8c', 'en-US', 'a time of 24 hours, like Monday or Tuesday', '{}'::text[], 'What day is it? asks for Monday, Tuesday and so on.', 'a2620cbc10f5198dd03e3f5a1569eb5dcf9a6a87') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('3735fcd6-ff29-588f-9596-c43f44c255ff', (select id from public.courses where slug = 'english'), 'week', 'noun', '/ˈwik/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('3735fcd6-ff29-588f-9596-c43f44c255ff', 'vi', 'tuần, tuần lễ', array['tuần', 'tuần lễ', 'một tuần']::text[], 'A week đứng sau số lượng nghĩa là mỗi tuần: five days a week (năm ngày mỗi tuần).', 'c0ee32d825d6ddb4025ab74af0609969ecc419c8') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('3735fcd6-ff29-588f-9596-c43f44c255ff', 'en-US', 'seven days, from Sunday to Saturday or from Monday to Sunday', '{}'::text[], 'After a number, a week means in every week: five days a week.', 'c0ee32d825d6ddb4025ab74af0609969ecc419c8') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
