insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('db50ab33-eb0a-5734-8acc-41ca6ebc979a', 'vi', 'vào (trước thứ, ngày); trên', array['vào', 'vào ngày', 'trên', 'ở trên']::text[], 'Trước thứ dùng on: on Monday. Không dùng in hay at.', 'db3d405b10675998c030223177d42e71b4e7a312') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('db50ab33-eb0a-5734-8acc-41ca6ebc979a', 'en-US', 'used before days and dates: on Monday; also means touching the top of something', '{}'::text[], 'Use on before a day: on Monday. Do not use in or at.', 'db3d405b10675998c030223177d42e71b4e7a312') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
