insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('64e68acc-d4b5-5477-a22a-27862bcd3b5d', 'be33fc6b-26f1-5729-b135-05c856f509f4', 1, 'What day is it? It''s Monday.', array['What day is it? It is Monday.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('64e68acc-d4b5-5477-a22a-27862bcd3b5d', 'vi', 'Hôm nay là thứ mấy? Thứ Hai.', array['Hôm nay thứ mấy? Thứ Hai.', 'Hôm nay là thứ mấy? Hôm nay là thứ Hai.', 'Hôm nay thứ mấy? Hôm nay thứ Hai.', 'Hôm nay thứ mấy? Thứ 2.', 'Hôm nay là thứ mấy? Thứ 2.']::text[], 'What day is it? hỏi thứ trong tuần. Câu trả lời dùng It''s: It''s Monday.', 'fa84156adc5064ef6f0b8bc4eec351e4d2326a9f') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('64e68acc-d4b5-5477-a22a-27862bcd3b5d', 'en-US', 'What day is it? It''s Monday.', '{}'::text[], 'What day is it? asks for the day of the week. Answer with It''s: It''s Monday.', 'fa84156adc5064ef6f0b8bc4eec351e4d2326a9f') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('23f5eda1-bb3d-52c6-8226-fdf6aba28edf', 'be33fc6b-26f1-5729-b135-05c856f509f4', 2, 'I work five days a week.', array['I work 5 days a week.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('23f5eda1-bb3d-52c6-8226-fdf6aba28edf', 'vi', 'Tôi làm việc năm ngày một tuần.', array['Tôi làm việc 5 ngày một tuần.', 'Tôi làm việc năm ngày mỗi tuần.', 'Tôi làm việc 5 ngày mỗi tuần.', 'Tôi đi làm 5 ngày một tuần.', 'Tôi đi làm năm ngày một tuần.', 'Mỗi tuần tôi làm việc năm ngày.', 'Mỗi tuần tôi làm việc 5 ngày.']::text[], 'A week ở đây nghĩa là mỗi tuần.', '4fd26f5d2d1fa0145dfd434542d88d13afe79283') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('23f5eda1-bb3d-52c6-8226-fdf6aba28edf', 'en-US', 'I work five days a week.', '{}'::text[], 'Here, a week means in every week.', '4fd26f5d2d1fa0145dfd434542d88d13afe79283') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('f45ae970-6c1c-53bd-9f42-8627394d7f38', 'be33fc6b-26f1-5729-b135-05c856f509f4', 3, 'I have class on Tuesdays and Thursdays.', array['I have a class on Tuesdays and Thursdays.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('f45ae970-6c1c-53bd-9f42-8627394d7f38', 'vi', 'Tôi có lớp học vào thứ Ba và thứ Năm hằng tuần.', array['Tôi có lớp vào các thứ Ba và thứ Năm.', 'Tôi có lớp học vào thứ Ba và thứ Năm hàng tuần.', 'Thứ Ba và thứ Năm hằng tuần tôi có lớp.', 'Tôi có lớp học vào thứ 3 và thứ 5 hằng tuần.', 'Tôi có lớp vào thứ 3 và thứ 5 hàng tuần.', 'Tôi có lớp học vào các thứ Ba và thứ Năm.']::text[], 'On Tuesdays (có -s) là thứ Ba nào cũng vậy. I have class là cách nói rất tự nhiên của người Mỹ: tôi có buổi học.', '2f21731eba3970f72fd440738e658197644dd05b') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('f45ae970-6c1c-53bd-9f42-8627394d7f38', 'en-US', 'I have class on Tuesdays and Thursdays.', '{}'::text[], 'On Tuesdays means every Tuesday. Americans often say I have class.', '2f21731eba3970f72fd440738e658197644dd05b') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('c7eb5df0-4695-5a54-86e9-41a30dcf2c98', 'be33fc6b-26f1-5729-b135-05c856f509f4', 4, 'See you on Wednesday!', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c7eb5df0-4695-5a54-86e9-41a30dcf2c98', 'vi', 'Hẹn gặp lại vào thứ Tư!', array['Hẹn gặp bạn vào thứ Tư!', 'Hẹn gặp lại thứ Tư!', 'Thứ Tư gặp lại nhé!', 'Hẹn gặp lại vào thứ 4!', 'Hẹn thứ 4 gặp lại!', 'Hẹn gặp lại thứ 4!']::text[], null, '2369a7229a6e1fe562d1ba0e27cd927fdd70ac23') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5e23f11a-ba37-5bb7-bd27-92eea948afa9', 'be33fc6b-26f1-5729-b135-05c856f509f4', 5, 'Is it Friday? No, it''s Thursday.', array['Is it Friday? No, it is Thursday.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5e23f11a-ba37-5bb7-bd27-92eea948afa9', 'vi', 'Hôm nay thứ Sáu à? Không, thứ Năm.', array['Hôm nay là thứ Sáu à? Không, hôm nay là thứ Năm.', 'Hôm nay có phải thứ Sáu không? Không, thứ Năm.', 'Hôm nay thứ Sáu à? Không, hôm nay thứ Năm.', 'Hôm nay thứ 6 à? Không, thứ 5.']::text[], null, '5b93fd6d99bd293268b7b3bfd58bbf46893aaef4') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
