insert into public.lessons (id, unit_id, sort_order, kind) values ('3e2828e8-ecc0-5037-b9bd-254906af3620', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'days-and-months'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('3e2828e8-ecc0-5037-b9bd-254906af3620', 'vi', 'Cuối tuần', 'Người Mỹ nói on the weekend (người Anh nói at the weekend). Trước today, next, last, this không dùng on hay in: See you next week, không nói See you on next week. Next week là tuần sau, next month là tháng sau. Last có hai nghĩa: trước (last week là tuần trước) và cuối cùng (my last day là ngày cuối cùng của tôi).', 'Saturday nhấn âm đầu: SAT-ur-day /ˈsætɚdeɪ/; giọng Mỹ đọc chữ t ở giữa rất nhanh, nghe gần như /d/. Weekend nhấn âm đầu: WEEK-end. Today thì ngược lại, nhấn âm sau: to-DAY /təˈdeɪ/. Month kết thúc bằng /nθ/: sau âm n, đưa đầu lưỡi ra giữa hai hàm răng và thổi hơi. Next /nɛkst/ và last /læst/: đọc rõ âm cuối /st/, đừng nuốt mất.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('3e2828e8-ecc0-5037-b9bd-254906af3620', 'en-US', 'The weekend', 'Americans say on the weekend. Do not use on or in before today, next, last or this: See you next week. Last can mean the one before this one (last week) or the one at the end (my last day).', 'Saturday: SAT-ur-day. In American English, the t sounds like a quick d. WEEK-end has stress on the first part, but to-DAY has stress on the second part. Month ends with /nθ/: put your tongue between your teeth after the n. Say the /st/ at the end of next and last.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
