insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('a6997d5a-4840-534c-a17b-02c4986469b0', 'vi', 'Chủ nhật', array['Chủ nhật', 'ngày Chủ nhật']::text[], 'Lịch của Mỹ thường bắt đầu tuần từ Sunday, không phải Monday.', 'bc5dd045b8623ddfc4bd0bce98ca5fda42accf88') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
