insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('2d4619bc-8147-5aab-b543-8c84c75bf81c', 'vi', 'sau, tới, tiếp theo', array['sau', 'tới', 'tiếp theo', 'kế tiếp']::text[], 'Next week là tuần sau. Không dùng on hay in trước next: next month, không nói in next month.', 'edee9402d198b04ac77dcf5dc9cc3dac44573782') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
