insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0eaa8c21-9140-5ae5-a960-3c92a8dac23e', 'vi', 'trước, vừa qua; cuối cùng', array['trước', 'vừa qua', 'cuối cùng', 'cuối']::text[], 'Last week là tuần trước (tuần vừa qua). My last day là ngày cuối cùng của tôi. Không dùng on hay in trước last.', '213ed3ea453bf610688ff8041e0a3b7b6abb5e6e') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('0eaa8c21-9140-5ae5-a960-3c92a8dac23e', 'en-US', 'the one before this one; or at the end, with no more after it', '{}'::text[], 'Last week is the week before this one. My last day is the day at the end. Do not use on or in before last.', '213ed3ea453bf610688ff8041e0a3b7b6abb5e6e') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('79761e60-6a32-53ba-b786-0fb9e720a141', '3e2828e8-ecc0-5037-b9bd-254906af3620', 1, 'Is today Saturday? No, it''s Sunday.', array['Is today Saturday? No, it is Sunday.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('79761e60-6a32-53ba-b786-0fb9e720a141', 'vi', 'Hôm nay là thứ Bảy à? Không, hôm nay là Chủ nhật.', array['Hôm nay thứ Bảy à? Không, Chủ nhật.', 'Hôm nay thứ Bảy à? Không, hôm nay Chủ nhật.', 'Hôm nay có phải thứ Bảy không? Không, hôm nay là Chủ nhật.', 'Hôm nay là thứ 7 à? Không, hôm nay là Chủ nhật.', 'Hôm nay thứ 7 à? Không, Chủ nhật.']::text[], null, 'cf22b936467f440d0db40e7b91240ec4de22dc7c') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('05e6d5bc-39e3-5634-ab04-03361f8293f4', '3e2828e8-ecc0-5037-b9bd-254906af3620', 2, 'I don''t work on the weekend.', array['I do not work on the weekend.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('05e6d5bc-39e3-5634-ab04-03361f8293f4', 'vi', 'Tôi không làm việc vào cuối tuần.', array['Tôi không đi làm vào cuối tuần.', 'Cuối tuần tôi không làm việc.', 'Cuối tuần tôi không đi làm.', 'Tôi không làm việc cuối tuần.', 'Tôi không đi làm cuối tuần.']::text[], 'Người Mỹ nói on the weekend; người Anh nói at the weekend.', '6f0cf36552e73bfbcbef062610cfec5fa9a827d2') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('05e6d5bc-39e3-5634-ab04-03361f8293f4', 'en-US', 'I don''t work on the weekend.', '{}'::text[], 'Americans say on the weekend. In England, people say at the weekend.', '6f0cf36552e73bfbcbef062610cfec5fa9a827d2') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('74812bc2-e159-500c-9854-99199481c6d8', '3e2828e8-ecc0-5037-b9bd-254906af3620', 3, 'See you next week. Have a good weekend!', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('74812bc2-e159-500c-9854-99199481c6d8', 'vi', 'Hẹn gặp lại tuần sau. Chúc cuối tuần vui vẻ!', array['Hẹn gặp bạn tuần sau. Chúc bạn cuối tuần vui vẻ!', 'Hẹn gặp lại tuần sau. Cuối tuần vui vẻ nhé!', 'Tuần sau gặp lại nhé. Cuối tuần vui vẻ!', 'Hẹn tuần sau gặp lại. Chúc cuối tuần vui vẻ!', 'Hẹn gặp lại vào tuần sau. Chúc cuối tuần vui vẻ!']::text[], 'Câu chào quen thuộc ở chỗ làm vào chiều thứ Sáu. Không nói on next week.', 'cb969adb82a7335a103bc485490226cab035e999') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('74812bc2-e159-500c-9854-99199481c6d8', 'en-US', 'See you next week. Have a good weekend!', '{}'::text[], 'People often say this at work on Friday afternoon. Do not say on next week.', 'cb969adb82a7335a103bc485490226cab035e999') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('11b3308f-054d-5cb5-be21-ce539a417295', '3e2828e8-ecc0-5037-b9bd-254906af3620', 4, 'I start my new job next month.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('11b3308f-054d-5cb5-be21-ce539a417295', 'vi', 'Tháng sau tôi bắt đầu công việc mới.', array['Tôi bắt đầu công việc mới vào tháng sau.', 'Tháng sau tôi sẽ bắt đầu công việc mới.', 'Tháng tới tôi bắt đầu công việc mới.', 'Tôi sẽ bắt đầu công việc mới vào tháng tới.', 'Tháng sau tôi bắt đầu làm công việc mới.']::text[], 'Việc đã lên lịch trong tương lai có thể dùng thì hiện tại: I start. Không nói in next month.', '32768c95015413a39be8c919d99398988a508859') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('11b3308f-054d-5cb5-be21-ce539a417295', 'en-US', 'I start my new job next month.', '{}'::text[], 'Use the present for a plan with a fixed date: I start. Do not say in next month.', '32768c95015413a39be8c919d99398988a508859') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('3c7784d4-b1ee-58b4-ae4b-ec4b188bec0d', '3e2828e8-ecc0-5037-b9bd-254906af3620', 5, 'Today is my last day here.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
