insert into public.lessons (id, unit_id, sort_order, kind) values ('d3f7cb23-934b-5146-9f85-545215716fa9', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'days-and-months'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('d3f7cb23-934b-5146-9f85-545215716fa9', 'vi', 'Tháng 1 đến tháng 6', 'Tên tháng luôn viết hoa: May, không viết may. Tiếng Anh gọi tháng bằng tên, không đánh số như tiếng Việt: tháng 5 là May, không nói month five. Trước tháng dùng in: in May (vào tháng Năm). Nhớ cặp này: on + thứ (on Monday), in + tháng (in May).', 'January /ˈdʒænjuɛri/ và February /ˈfɛbjuɛri/ nhấn âm đầu: JAN-u-ar-y, FEB-u-ar-y. Trong February, nhiều người Mỹ không đọc chữ r đầu tiên; cả hai cách đều đúng. January và June bắt đầu bằng /dʒ/ như chữ j trong job: đầu lưỡi chạm lợi trên rồi bật ra, môi hơi tròn, cổ họng rung; đừng đọc thành d hay gi của tiếng Việt. April nhấn âm đầu: A-pril /ˈeɪprəl/. Birthday có âm /θ/ ở giữa: BIRTH-day, đưa đầu lưỡi ra giữa hai hàm răng.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('d3f7cb23-934b-5146-9f85-545215716fa9', 'en-US', 'January to June', 'Months always start with a capital letter: May. Use in before a month: in May. Remember: on Monday, in May.', 'JAN-u-ar-y and FEB-u-ar-y have stress on the first part. Many Americans do not say the first r in February; both ways are fine. January and June start with /dʒ/, like the j in job. A-pril has stress on the first part. In birthday, put your tongue between your teeth for th.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
