insert into public.lessons (id, unit_id, sort_order, kind) values ('1c340b70-d14f-5e45-8d2d-92d2ae695d02', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'days-and-months'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('1c340b70-d14f-5e45-8d2d-92d2ae695d02', 'vi', 'Tháng 7 đến tháng 12', 'Hỏi khi nào dùng When: When is your birthday? Trả lời bằng in + tháng (It''s in July) hoặc on + ngày cụ thể (It''s on July first). Người Mỹ nói tháng trước, ngày sau: July first là ngày 1 tháng 7, và viết là 7/1, ngược với cách viết 1/7 của người Việt. Ngày trong tháng đọc bằng số thứ tự: viết October 1 nhưng đọc October first, không đọc October one.', 'July nhấn âm sau: ju-LY /dʒuˈlaɪ/, khác với June chỉ có một âm tiết. September, October, November, December đều nhấn âm thứ hai: sep-TEM-ber, oc-TO-ber, no-VEM-ber, de-CEM-ber; đuôi -ber đọc nhẹ và cong lưỡi /bɚ/. August nhấn âm đầu: AU-gust. When đọc /wɛn/, chữ h không đọc. First /fɝst/: cong lưỡi ở âm giữa và đọc rõ đuôi /st/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('1c340b70-d14f-5e45-8d2d-92d2ae695d02', 'en-US', 'July to December', 'Use when to ask about time: When is your birthday? Answer with in + month (in July) or on + date (on July first). Americans say the month first: July first, written 7/1. For dates, say first, not one, even when you write October 1.', 'July has stress on the second part: ju-LY. September, October, November and December also have stress on the second part: sep-TEM-ber, oc-TO-ber, no-VEM-ber, de-CEM-ber. AU-gust has stress on the first part. Do not say the h in when. Say the /st/ at the end of first.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
