insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('2c6ba8a5-ef99-5813-8f65-c35323fc70ab', 'vi', 'tháng Mười Hai', array['tháng Mười Hai', 'tháng 12']::text[], 'December là tháng 12 dương lịch. Tháng Chạp thường dùng cho tháng 12 âm lịch.', '65640c6577c9c72497525e656127b5bd1deb6f85') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
