insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('fe7a117f-4625-530c-90cf-af81e5e3ae3f', (select id from public.courses where slug = 'english'), 'when', 'adverb', '/ˈwɛn/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('fe7a117f-4625-530c-90cf-af81e5e3ae3f', 'vi', 'khi nào, lúc nào, bao giờ', array['khi nào', 'lúc nào', 'bao giờ', 'khi']::text[], 'When hỏi thời điểm nói chung (ngày, tháng). Hỏi mấy giờ thì thường dùng What time.', '30603fa9e0f620c305cd627ab0ff138a960c48bd') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('fe7a117f-4625-530c-90cf-af81e5e3ae3f', 'en-US', 'at what time; used to ask about a day, month or year', '{}'::text[], 'When asks about a day or month. To ask the hour, people often say What time.', '30603fa9e0f620c305cd627ab0ff138a960c48bd') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('3478fe3f-d920-5c47-b4d7-f797f9a31e1a', (select id from public.courses where slug = 'english'), 'first', 'number', '/ˈfɝst/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('3478fe3f-d920-5c47-b4d7-f797f9a31e1a', 'vi', 'thứ nhất, đầu tiên; mồng 1 (ngày trong tháng)', array['thứ nhất', 'đầu tiên', 'ngày 1', 'mồng 1', 'mồng một', 'mùng 1', 'mùng một', 'ngày mồng 1', 'ngày mùng 1']::text[], 'Ngày 1 trong tháng nói là first: October first. Viết October 1 nhưng vẫn đọc là October first.', 'e0996a37c13d44c3b06074939d43fa3759bd32c1') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('3478fe3f-d920-5c47-b4d7-f797f9a31e1a', 'en-US', 'number one in order; the date 1, as in July first', '{}'::text[], 'For the date, say first: October first. You can write October 1, but you say October first.', 'e0996a37c13d44c3b06074939d43fa3759bd32c1') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5af98848-47b8-528c-82af-02e6657cac6b', '1c340b70-d14f-5e45-8d2d-92d2ae695d02', 1, 'When is your birthday? It''s in November.', array['When is your birthday? It is in November.', 'When''s your birthday? It''s in November.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5af98848-47b8-528c-82af-02e6657cac6b', 'vi', 'Sinh nhật bạn là khi nào? Vào tháng Mười Một.', array['Sinh nhật của bạn là khi nào? Vào tháng Mười Một.', 'Sinh nhật bạn là bao giờ? Vào tháng Mười Một.', 'Khi nào là sinh nhật bạn? Vào tháng Mười Một.', 'Sinh nhật bạn khi nào? Vào tháng 11.', 'Sinh nhật bạn khi nào? Vào tháng Mười Một.', 'Sinh nhật bạn là khi nào? Tháng 11.', 'Sinh nhật bạn là khi nào? Vào tháng 11.']::text[], null, '53b017756541d7eacb609a64effb5768e393016b') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('654e4771-e06e-52b0-bc37-f75e6b1473ae', '1c340b70-d14f-5e45-8d2d-92d2ae695d02', 2, 'My birthday is on October first.', array['My birthday is on October 1.', 'My birthday is on October 1st.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('654e4771-e06e-52b0-bc37-f75e6b1473ae', 'vi', 'Sinh nhật tôi là ngày 1 tháng 10.', array['Sinh nhật tôi vào ngày 1 tháng 10.', 'Sinh nhật của tôi là ngày 1 tháng 10.', 'Sinh nhật tôi là ngày mồng 1 tháng 10.', 'Sinh nhật tôi là mồng 1 tháng 10.', 'Sinh nhật tôi là ngày mùng 1 tháng 10.', 'Sinh nhật tôi vào ngày mồng một tháng Mười.', 'Sinh nhật tôi là ngày 1/10.']::text[], 'Ngày cụ thể dùng on. Người Mỹ nói tháng trước rồi đến ngày, và viết là 10/1. Người Việt viết là 1/10.', 'f6f7e0ce5e6a55dff34792f7faf3aa04254b7ac2') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('654e4771-e06e-52b0-bc37-f75e6b1473ae', 'en-US', 'My birthday is on October first.', '{}'::text[], 'Use on with a date. Americans say the month first and write 10/1.', 'f6f7e0ce5e6a55dff34792f7faf3aa04254b7ac2') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('e3371f82-e498-541f-bca8-3f3979a01c2d', '1c340b70-d14f-5e45-8d2d-92d2ae695d02', 3, 'My children have no school in July and August.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e3371f82-e498-541f-bca8-3f3979a01c2d', 'vi', 'Các con tôi được nghỉ học vào tháng Bảy và tháng Tám.', array['Các con tôi nghỉ học vào tháng Bảy và tháng Tám.', 'Các con tôi được nghỉ học vào tháng 7 và tháng 8.', 'Con tôi nghỉ học vào tháng 7 và tháng 8.', 'Tháng Bảy và tháng Tám các con tôi được nghỉ học.', 'Các con tôi không phải đi học vào tháng 7 và tháng 8.', 'Các con tôi không đi học vào tháng Bảy và tháng Tám.']::text[], 'Have no school là không có buổi học, được nghỉ học.', '5d42b14a073067bb5638b8ff450adfea0c7254cd') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('e3371f82-e498-541f-bca8-3f3979a01c2d', 'en-US', 'My children have no school in July and August.', '{}'::text[], 'Have no school means there are no classes.', '5d42b14a073067bb5638b8ff450adfea0c7254cd') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('525c3340-e61e-5bf1-9820-1e97e6987f0b', '1c340b70-d14f-5e45-8d2d-92d2ae695d02', 4, 'When do you start? On September first.', array['When do you start? On September 1.', 'When do you start? September first.', 'When do you start? On September 1st.', 'When do you start? September 1st.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('525c3340-e61e-5bf1-9820-1e97e6987f0b', 'vi', 'Khi nào bạn bắt đầu? Vào ngày 1 tháng 9.', array['Bao giờ bạn bắt đầu? Vào ngày 1 tháng 9.', 'Bạn bắt đầu khi nào? Ngày 1 tháng 9.', 'Khi nào bạn bắt đầu? Ngày mồng 1 tháng 9.', 'Bạn bắt đầu vào khi nào? Vào ngày 1 tháng 9.', 'Khi nào bạn bắt đầu? Mồng 1 tháng Chín.', 'Khi nào bạn bắt đầu? Mùng 1 tháng 9.']::text[], 'Câu hỏi quen thuộc khi ai đó sắp nhận việc mới hay vào khóa học mới.', '8c155c99d5ea78bb76054fc810654e17aa5572a6') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('525c3340-e61e-5bf1-9820-1e97e6987f0b', 'en-US', 'When do you start? On September first.', '{}'::text[], 'People ask this about a new job or a new class.', '8c155c99d5ea78bb76054fc810654e17aa5572a6') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('6e2d0ac6-01ce-5c5d-95c4-b314840787e0', '1c340b70-d14f-5e45-8d2d-92d2ae695d02', 5, 'Christmas is in December.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('6e2d0ac6-01ce-5c5d-95c4-b314840787e0', 'vi', 'Lễ Giáng sinh vào tháng Mười Hai.', array['Giáng sinh vào tháng Mười Hai.', 'Lễ Giáng sinh vào tháng 12.', 'Giáng sinh là vào tháng 12.', 'Giáng sinh rơi vào tháng 12.', 'Noel vào tháng 12.', 'Giáng sinh vào tháng 12.']::text[], null, '22c597d72b42867cf3b3fe63f0036f353f936d99') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
