insert into public.lessons (id, unit_id, sort_order, kind) values ('dc3b8008-9238-5365-9473-48878eaf0692', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'daily-routine'), 1, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('dc3b8008-9238-5365-9473-48878eaf0692', 'vi', 'Các bữa ăn', 'Hiện tại đơn dùng để nói thói quen, việc làm hằng ngày. Với I, you, we, they, động từ giữ nguyên: I eat, we eat. Không thêm am, are trước động từ: nói I wake up, không nói I am wake up. Trước tên bữa ăn không dùng a, the: eat breakfast, have lunch. Ở nhà là at home; về nhà là go home, không có to.', 'Chủ đề này luyện hai âm /iː/ và /ɪ/. /iː/ trong eat /iːt/: kéo môi sang hai bên như đang cười, lưỡi căng. /ɪ/ trong dinner /ˈdɪnɚ/: ngắn, thả lỏng, miệng mở hơn một chút, nghe gần giữa i và ê. Eat và it /ɪt/ chỉ khác nhau ở âm này. Từ điển Mỹ đôi khi ghi /iː/ là /i/. Trong breakfast /ˈbrɛkfəst/, chữ ea đọc như e: BREK-fast.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('dc3b8008-9238-5365-9473-48878eaf0692', 'en-US', 'Meals', 'Use the present simple for things you do every day. With I, you, we and they, use the base verb: I eat, we eat. Do not add am or are: say I wake up, not I am wake up. Say eat breakfast or have lunch, with no a or the. Say at home and go home, with no to.', 'This unit practices /iː/ and /ɪ/. For /iː/ in eat, smile and keep your tongue tight. For /ɪ/ in dinner, say it short and relaxed. Eat and it are different words. In breakfast, the ea sounds like e: BREK-fast.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('fb14daaa-9b8e-569d-a9e1-aa4cbc84ec23', (select id from public.courses where slug = 'english'), 'wake', 'verb', '/ˈweɪk/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('fb14daaa-9b8e-569d-a9e1-aa4cbc84ec23', 'vi', 'thức dậy, tỉnh giấc', array['thức dậy', 'tỉnh dậy', 'thức giấc', 'tỉnh giấc', 'dậy']::text[], 'Thường nói wake up. Wake up là tỉnh giấc, mở mắt; get up là rời khỏi giường.', '07edc5e242b2a123a9e0772c99c8b4ce1b248ce3') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('fb14daaa-9b8e-569d-a9e1-aa4cbc84ec23', 'en-US', 'to stop sleeping', '{}'::text[], 'We usually say wake up. Wake up means you stop sleeping; get up means you get out of bed.', '07edc5e242b2a123a9e0772c99c8b4ce1b248ce3') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
