insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('ae1c1c8d-6d68-5097-a967-efa7a86efeed', 'vi', 'bữa sáng', array['bữa sáng', 'bữa ăn sáng', 'điểm tâm', 'bữa điểm tâm']::text[], 'Không dùng a, the: eat breakfast, have breakfast (ăn sáng).', '9e3a8225470fb3b95925da28e9a3f0f077649838') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('ae1c1c8d-6d68-5097-a967-efa7a86efeed', 'en-US', 'the first meal of the day', '{}'::text[], 'No a or the: eat breakfast, have breakfast.', '9e3a8225470fb3b95925da28e9a3f0f077649838') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
