insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('af191d05-6602-5ecd-8da6-887b84c8f86f', 'vi', 'bữa tối', array['bữa tối', 'bữa ăn tối', 'cơm tối']::text[], 'Không dùng a, the: eat dinner, have dinner (ăn tối).', '78cbc77f583dd8082f08804b0579daad54c5771c') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('af191d05-6602-5ecd-8da6-887b84c8f86f', 'en-US', 'the main meal of the day, usually in the evening', '{}'::text[], 'No a or the: eat dinner, have dinner.', '78cbc77f583dd8082f08804b0579daad54c5771c') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
