insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7a4573d7-d96a-5a54-994e-81daa5e50b58', 'vi', 'ăn', array['ăn']::text[], 'Ăn một bữa có thể nói eat hoặc have: eat lunch, have lunch đều đúng.', 'd89455758ecc0f43a4a9ea5c37e24194722042f9') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7a4573d7-d96a-5a54-994e-81daa5e50b58', 'en-US', 'to put food in your mouth and swallow it', '{}'::text[], 'For meals, you can say eat or have: eat lunch, have lunch.', 'd89455758ecc0f43a4a9ea5c37e24194722042f9') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
