insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('d8212bfe-5fc7-52a6-aea8-859ee186f2dd', 'vi', 'nhà, nơi mình sống', array['nhà', 'ở nhà', 'nơi ở', 'nhà mình']::text[], 'Ở nhà là at home. Về nhà là go home, không nói go to home.', 'e83249bd3ba79932e16fb1fb5100dafade9954c2') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('d8212bfe-5fc7-52a6-aea8-859ee186f2dd', 'en-US', 'the place where you live', '{}'::text[], 'Say at home. Say go home, not go to home.', 'e83249bd3ba79932e16fb1fb5100dafade9954c2') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('dd477fe9-a496-593e-bbf1-dd42cbfa62f5', 'dc3b8008-9238-5365-9473-48878eaf0692', 1, 'I wake up at six thirty every day.', array['I wake up at 6:30 every day.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('dd477fe9-a496-593e-bbf1-dd42cbfa62f5', 'vi', 'Ngày nào tôi cũng thức dậy lúc sáu giờ rưỡi.', array['Tôi thức dậy lúc sáu giờ rưỡi mỗi ngày.', 'Hằng ngày tôi thức dậy lúc sáu giờ rưỡi.', 'Tôi thức dậy lúc sáu giờ ba mươi mỗi ngày.', 'Mỗi ngày tôi thức dậy lúc 6 giờ 30.', 'Tôi dậy lúc sáu rưỡi mỗi ngày.', 'Ngày nào tôi cũng dậy lúc sáu giờ rưỡi.']::text[], null, '921eb079a53ba479fa9001d82629fa19f1bba929') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('05a820ff-49b5-5634-be8c-4b92e08e5f8a', 'dc3b8008-9238-5365-9473-48878eaf0692', 2, 'We eat breakfast at home.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('05a820ff-49b5-5634-be8c-4b92e08e5f8a', 'vi', 'Chúng tôi ăn sáng ở nhà.', array['Chúng tôi ăn bữa sáng ở nhà.', 'Chúng tôi ăn sáng tại nhà.', 'Chúng mình ăn sáng ở nhà.', 'Chúng ta ăn sáng ở nhà.']::text[], null, '660490771ad25d731c97bec54c6471147af5679f') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('0bcdcb89-a75d-5926-8b76-164ff8b22c4c', 'dc3b8008-9238-5365-9473-48878eaf0692', 3, 'I have lunch with my friends at work.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('0bcdcb89-a75d-5926-8b76-164ff8b22c4c', 'vi', 'Tôi ăn trưa với bạn bè ở chỗ làm.', array['Tôi ăn trưa cùng bạn bè ở chỗ làm.', 'Tôi ăn trưa với các bạn ở chỗ làm.', 'Tôi ăn trưa với bạn bè ở công ty.', 'Tôi ăn trưa với bạn bè ở cơ quan.', 'Tôi ăn trưa với bạn bè ở nơi làm việc.']::text[], 'Have lunch cũng là ăn trưa. At work là ở chỗ làm, không có the.', '02d65459a21731f674c2cd73f01d98a247f9ff3f') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('0bcdcb89-a75d-5926-8b76-164ff8b22c4c', 'en-US', 'I have lunch with my friends at work.', '{}'::text[], 'Have lunch means eat lunch. Say at work, with no the.', '02d65459a21731f674c2cd73f01d98a247f9ff3f') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('839d56ea-9315-5e69-9d29-d3ef6946a2ec', 'dc3b8008-9238-5365-9473-48878eaf0692', 4, 'What time do you eat dinner? At seven.', array['What time do you eat dinner? At 7.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('839d56ea-9315-5e69-9d29-d3ef6946a2ec', 'vi', 'Bạn ăn tối lúc mấy giờ? Lúc bảy giờ.', array['Mấy giờ bạn ăn tối? Lúc bảy giờ.', 'Bạn ăn tối lúc mấy giờ? Bảy giờ.', 'Mấy giờ bạn ăn tối? Bảy giờ.', 'Các bạn ăn tối lúc mấy giờ? Lúc bảy giờ.', 'Bạn ăn tối lúc mấy giờ? Lúc 7 giờ.', 'Bạn ăn cơm tối lúc mấy giờ? Lúc bảy giờ.']::text[], null, '06f9fb9eb837d27b7cbeaf1dc15131aa1375c2b7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('3bcb2cb2-f6c3-5be9-b765-b8595e22dfd8', 'dc3b8008-9238-5365-9473-48878eaf0692', 5, 'I go home and eat dinner with my family.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('3bcb2cb2-f6c3-5be9-b765-b8595e22dfd8', 'vi', 'Tôi về nhà và ăn tối cùng gia đình.', array['Tôi về nhà và ăn tối với gia đình.', 'Tôi về nhà rồi ăn tối cùng gia đình.', 'Tôi về nhà và ăn tối với gia đình tôi.', 'Tôi về nhà và ăn tối cùng gia đình mình.', 'Tôi về nhà ăn tối với gia đình.']::text[], 'Go home không có to. Hai động từ go và eat cùng giữ nguyên dạng.', 'b06cc93793ed72a3bd3d04e4ec5ec93a403229a9') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('3bcb2cb2-f6c3-5be9-b765-b8595e22dfd8', 'en-US', 'I go home and eat dinner with my family.', '{}'::text[], 'Say go home, with no to. Both verbs, go and eat, stay in the base form.', 'b06cc93793ed72a3bd3d04e4ec5ec93a403229a9') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
