insert into public.lessons (id, unit_id, sort_order, kind) values ('04f71fe6-9657-5472-81d5-3105e1f4e902', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'daily-routine'), 2, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('04f71fe6-9657-5472-81d5-3105e1f4e902', 'vi', 'Buổi sáng', 'Kể việc theo thứ tự với first (đầu tiên) và then (sau đó): First I eat breakfast, then I go to work. Với bộ phận cơ thể, tiếng Anh phải có my, your, their...: wash my face (rửa mặt), brush my teeth (đánh răng). Tắm vòi sen là take a shower, nhớ có a.', 'Teeth /tiːθ/ có âm /iː/ dài; số ít tooth /tuːθ/ có âm u dài. Âm /θ/ cuối hai từ này: đặt đầu lưỡi giữa hai hàm răng rồi thổi hơi, cổ họng không rung; đừng đọc thành /t/ hay /s/. Then /ðɛn/ cũng đặt lưỡi giữa hai hàm răng nhưng cổ họng rung. Shower đọc /ˈʃaʊɚ/: SHOW-er, phần đầu có âm ao. Đọc rõ âm /ʃ/ cuối wash, brush.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('04f71fe6-9657-5472-81d5-3105e1f4e902', 'en-US', 'In the morning', 'Use first and then to tell things in order: First I eat breakfast, then I go to work. With body parts, use my, your or their: wash my face, brush my teeth. Say take a shower, with a.', 'Teeth has a long /iː/. Tooth has a long u. At the end of both, put your tongue between your teeth and blow: /θ/. Then starts with /ð/: tongue between your teeth, with voice. Shower sounds like SHOW-er, with ow as in now. Say the /ʃ/ at the end of wash and brush.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
