insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('36d4069d-6aee-5c33-b7aa-461db0fe4bf0', 'vi', 'chải, đánh (răng)', array['chải', 'đánh']::text[], 'Brush my teeth là đánh răng. Brush còn là danh từ: cái bàn chải.', '0f44510572409abb97a10b4d73c47798e9a56eb4') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('36d4069d-6aee-5c33-b7aa-461db0fe4bf0', 'en-US', 'to clean something, like your teeth or hair, with a brush', '{}'::text[], 'Brush my teeth means clean my teeth. Brush is also a noun: a thing you clean with.', '0f44510572409abb97a10b4d73c47798e9a56eb4') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
