insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7f2450b8-cb5f-5349-88bb-8224bf9d7715', 'vi', 'lấy, cầm; take a shower là tắm', array['lấy', 'cầm', 'mang', 'đem']::text[], 'Take có nhiều nghĩa, tùy từ đi kèm. Take a shower là tắm (vòi sen), không dịch từng chữ.', '53bd7d992ed7edf9a271056d254d8f7797462f27') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7f2450b8-cb5f-5349-88bb-8224bf9d7715', 'en-US', 'to get something in your hand; also used in take a shower', '{}'::text[], 'Take has many uses. Take a shower means wash your body under a shower.', '53bd7d992ed7edf9a271056d254d8f7797462f27') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
