insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('145def16-e574-5721-9228-07593a9753a2', 'vi', 'vòi sen; việc tắm vòi sen', array['vòi sen', 'vòi hoa sen', 'tắm vòi sen', 'tắm']::text[], 'Tắm là take a shower, nhớ có a: không nói I take shower.', '80136de85bbef43dd79437812346b15330ab5d8f') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
