insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('36a64a8e-b642-5df0-b530-6f8f098a0802', 'vi', 'sau đó, rồi', array['sau đó', 'rồi', 'sau đấy', 'tiếp đó']::text[], 'Đừng nhầm then (sau đó) với than (hơn), hai từ đọc gần giống nhau.', '6f8f8e9f767353d846d34ea5a451c83849c1b01b') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
