insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('c4f8cb84-05ea-5f2d-bd3a-4e10d545b0db', '04f71fe6-9657-5472-81d5-3105e1f4e902', 1, 'I wake up and wash my face.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c4f8cb84-05ea-5f2d-bd3a-4e10d545b0db', 'vi', 'Tôi thức dậy và rửa mặt.', array['Tôi thức dậy rồi rửa mặt.', 'Tôi ngủ dậy và rửa mặt.', 'Tôi ngủ dậy rồi rửa mặt.', 'Tôi dậy và rửa mặt.']::text[], 'Tiếng Việt nói rửa mặt, tiếng Anh phải nói wash my face.', '06b7fd86862a8d6d12047f31943f0f02e9649588') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c4f8cb84-05ea-5f2d-bd3a-4e10d545b0db', 'en-US', 'I wake up and wash my face.', '{}'::text[], 'Say wash my face, with my.', '06b7fd86862a8d6d12047f31943f0f02e9649588') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('3b40e26e-0d73-5141-be6b-c49c1cb61950', '04f71fe6-9657-5472-81d5-3105e1f4e902', 2, 'Then I brush my teeth.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('3b40e26e-0d73-5141-be6b-c49c1cb61950', 'vi', 'Sau đó tôi đánh răng.', array['Rồi tôi đánh răng.', 'Sau đấy tôi đánh răng.', 'Tiếp đó tôi đánh răng.']::text[], null, '0e27d6db53652da9d8787f3f58c5667acc07f25c') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('759725b2-66da-59f6-a4ae-eb0ed71e521b', '04f71fe6-9657-5472-81d5-3105e1f4e902', 3, 'When do you take a shower? At night.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('759725b2-66da-59f6-a4ae-eb0ed71e521b', 'vi', 'Bạn tắm lúc nào? Buổi tối.', array['Bạn tắm vào lúc nào? Vào buổi tối.', 'Bạn tắm khi nào? Buổi tối.', 'Bạn thường tắm lúc nào? Buổi tối.', 'Bạn tắm lúc nào? Vào buổi tối.', 'Bạn tắm lúc nào? Ban đêm.']::text[], 'Nói in the morning, in the evening nhưng at night.', '3af1924b515cc2f8a35ca7f7c7d018ae42076fe7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('759725b2-66da-59f6-a4ae-eb0ed71e521b', 'en-US', 'When do you take a shower? At night.', '{}'::text[], 'Say in the morning and in the evening, but at night.', '3af1924b515cc2f8a35ca7f7c7d018ae42076fe7') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('b2182d96-55a6-590e-9e62-1c97e58e836e', '04f71fe6-9657-5472-81d5-3105e1f4e902', 4, 'First I eat breakfast, then I go to work.', array['First, I eat breakfast, then I go to work.', 'First I eat breakfast. Then I go to work.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('b2182d96-55a6-590e-9e62-1c97e58e836e', 'vi', 'Đầu tiên tôi ăn sáng, sau đó tôi đi làm.', array['Đầu tiên tôi ăn sáng, rồi tôi đi làm.', 'Trước tiên tôi ăn sáng, sau đó đi làm.', 'Trước hết tôi ăn sáng, rồi đi làm.', 'Tôi ăn sáng trước, rồi đi làm.', 'Đầu tiên tôi ăn sáng, sau đó đi làm.']::text[], 'Go to work là đi làm, không có the.', '478400a782eb03d721787e7944f162cd82673359') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('b2182d96-55a6-590e-9e62-1c97e58e836e', 'en-US', 'First I eat breakfast, then I go to work.', '{}'::text[], 'Say go to work, with no the.', '478400a782eb03d721787e7944f162cd82673359') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('577646d7-dbc6-546f-a84c-b607dcfa0b52', '04f71fe6-9657-5472-81d5-3105e1f4e902', 5, 'My children brush their teeth and wash their faces.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('577646d7-dbc6-546f-a84c-b607dcfa0b52', 'vi', 'Các con tôi đánh răng và rửa mặt.', array['Các con tôi đánh răng rồi rửa mặt.', 'Các con của tôi đánh răng và rửa mặt.', 'Con tôi đánh răng và rửa mặt.', 'Bọn trẻ nhà tôi đánh răng và rửa mặt.', 'Lũ trẻ nhà tôi đánh răng và rửa mặt.']::text[], 'Nhiều người thì dùng their và số nhiều: their faces.', '954d649d9af6d419a33cd72d5b7bcc69a9159e37') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('577646d7-dbc6-546f-a84c-b607dcfa0b52', 'en-US', 'My children brush their teeth and wash their faces.', '{}'::text[], 'For more than one person, use their and the plural: their faces.', '954d649d9af6d419a33cd72d5b7bcc69a9159e37') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
