insert into public.lessons (id, unit_id, sort_order, kind) values ('8050f34f-24a2-5b41-80b0-f1d22ffc570f', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'daily-routine'), 3, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('8050f34f-24a2-5b41-80b0-f1d22ffc570f', 'vi', 'Buổi tối', 'Phủ định với I, you, we, they: thêm don''t trước động từ: I don''t watch TV. Câu hỏi: Do + chủ ngữ + động từ? Do you watch TV? Trả lời ngắn: Yes, I do. hoặc No, I don''t. After (sau) và before (trước) đứng trước danh từ: after dinner, before dinner. Xem ti vi là watch TV, không có the.', 'Sleep /sliːp/ có âm /iː/ dài, môi kéo sang hai bên; đừng đọc ngắn thành slip /slɪp/ (trượt). TV đọc /ˌtiːˈviː/, hai âm /iː/, nhấn vào âm sau: tee-VEE. Before /bɪˈfɔr/ có âm /ɪ/ ngắn và nhấn vào âm sau: be-FORE. After nhấn âm đầu: AF-ter, chữ a đọc /æ/, miệng mở rộng.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('8050f34f-24a2-5b41-80b0-f1d22ffc570f', 'en-US', 'In the evening', 'To make a negative with I, you, we and they, put don''t before the verb: I don''t watch TV. To ask, start with Do: Do you watch TV? Short answers: Yes, I do. No, I don''t. Use after and before with a noun: after dinner, before dinner. Say watch TV, with no the.', 'Sleep has a long /iː/. Do not say slip. TV has two long /iː/ sounds, and the second is strong: tee-VEE. Before has a short /ɪ/, and the second part is strong: be-FORE. In after, the first part is strong: AF-ter.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('85e44fde-5d0c-56e1-8e42-05f6f14fa178', (select id from public.courses where slug = 'english'), 'come', 'verb', '/ˈkəm/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('85e44fde-5d0c-56e1-8e42-05f6f14fa178', 'vi', 'đến, tới', array['đến', 'tới', 'đi đến']::text[], 'Come là đến phía người nói; go là đi khỏi chỗ người nói. Come back là quay về, trở lại.', 'd88d473b374eed7046db3c2a4ddcb91a88cbad76') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('85e44fde-5d0c-56e1-8e42-05f6f14fa178', 'en-US', 'to move to the place where you are, or to here', '{}'::text[], 'Come means move toward here; go means move away. Come back means return.', 'd88d473b374eed7046db3c2a4ddcb91a88cbad76') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('6ca5dd37-7a64-58a4-b68e-24a3e99e0cf1', (select id from public.courses where slug = 'english'), 'back', 'adverb', '/ˈbæk/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('6ca5dd37-7a64-58a4-b68e-24a3e99e0cf1', 'vi', 'trở lại, về (chỗ cũ)', array['trở lại', 'quay lại', 'quay về', 'trở về', 'về']::text[], 'Come back from work là đi làm về.', '61bb8d29b5be7db307cb29005bff087ebe300454') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('6ca5dd37-7a64-58a4-b68e-24a3e99e0cf1', 'en-US', 'to the place you were before', '{}'::text[], 'Come back from work means return home after work.', '61bb8d29b5be7db307cb29005bff087ebe300454') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('283d1dfc-b38b-52b5-a1d6-67f08ea5c060', (select id from public.courses where slug = 'english'), 'after', 'preposition', '/ˈæftɝ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('283d1dfc-b38b-52b5-a1d6-67f08ea5c060', 'vi', 'sau, sau khi', array['sau', 'sau khi']::text[], 'After + danh từ: after dinner (sau bữa tối), after work (sau giờ làm).', '405906c9d5be6ae5393ca65fb0e7c38e0d585ecb') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('283d1dfc-b38b-52b5-a1d6-67f08ea5c060', 'en-US', 'later than something', '{}'::text[], 'Use a noun after it: after dinner, after work.', '405906c9d5be6ae5393ca65fb0e7c38e0d585ecb') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('7569c8c9-ad22-52d3-98af-05681c6175c3', (select id from public.courses where slug = 'english'), 'before', 'preposition', '/bɪˈfɔɹ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7569c8c9-ad22-52d3-98af-05681c6175c3', 'vi', 'trước, trước khi', array['trước', 'trước khi']::text[], 'Before + danh từ: before dinner. Before cũng đứng trước cả một câu: before I go to sleep (trước khi tôi đi ngủ).', '51de2b835bd35a67eb32dbcd3d77d4b96e5aa39d') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7569c8c9-ad22-52d3-98af-05681c6175c3', 'en-US', 'earlier than something', '{}'::text[], 'Use a noun after it: before dinner. You can also use a sentence: before I go to sleep.', '51de2b835bd35a67eb32dbcd3d77d4b96e5aa39d') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('ec496786-1cf4-54c0-96db-ee24c0bef14f', (select id from public.courses where slug = 'english'), 'watch', 'verb', '/ˈwɑtʃ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('ec496786-1cf4-54c0-96db-ee24c0bef14f', 'vi', 'xem, theo dõi', array['xem', 'coi', 'theo dõi']::text[], 'Watch còn là danh từ: đồng hồ đeo tay (đã học). Xem ti vi là watch TV, không có the.', '292b0901993f7e9d9a0d9b80542f9e59505ba5be') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('ec496786-1cf4-54c0-96db-ee24c0bef14f', 'en-US', 'to look at something for some time', '{}'::text[], 'Watch is also a noun: a small clock you wear. Say watch TV, with no the.', '292b0901993f7e9d9a0d9b80542f9e59505ba5be') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('35729519-a077-5a50-acab-01375a8671ad', (select id from public.courses where slug = 'english'), 'TV', 'noun', '/ˈtiˈvi/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('35729519-a077-5a50-acab-01375a8671ad', 'vi', 'ti vi, truyền hình', array['ti vi', 'tivi', 'vô tuyến', 'truyền hình', 'máy truyền hình']::text[], 'Xem ti vi là watch TV, không có the. Khi nói về cái máy thì có thể dùng the: The TV is big.', '56ab49a5c68f11cc45c651da6a3f339eff2853f8') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('35729519-a077-5a50-acab-01375a8671ad', 'en-US', 'television; a machine for watching shows and news', '{}'::text[], 'Say watch TV, with no the. For the machine, you can say the TV: The TV is big.', '56ab49a5c68f11cc45c651da6a3f339eff2853f8') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('7578f688-125a-58e3-b5e8-b6d6ebbc4a44', (select id from public.courses where slug = 'english'), 'sleep', 'verb', '/ˈslip/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7578f688-125a-58e3-b5e8-b6d6ebbc4a44', 'vi', 'ngủ', array['ngủ']::text[], 'Sleep là ngủ; go to sleep là đi ngủ, bắt đầu ngủ. Nói giờ đi ngủ thì dùng go to sleep: I go to sleep at eleven.', 'c3ca5f787365eae0dea86250e27d476406956478') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('7578f688-125a-58e3-b5e8-b6d6ebbc4a44', 'en-US', 'to rest with your eyes closed, as you do at night', '{}'::text[], 'Sleep means be asleep. Go to sleep means start to sleep: I go to sleep at eleven.', 'c3ca5f787365eae0dea86250e27d476406956478') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('5ecf818f-ba4a-5729-a4eb-8a6f050d31d8', '8050f34f-24a2-5b41-80b0-f1d22ffc570f', 1, 'I come back from work at six.', array['I come back from work at 6.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('5ecf818f-ba4a-5729-a4eb-8a6f050d31d8', 'vi', 'Tôi đi làm về lúc sáu giờ.', array['Sáu giờ tôi đi làm về.', 'Tôi đi làm về lúc 6 giờ.', 'Tôi từ chỗ làm về lúc sáu giờ.', 'Tôi đi làm về vào lúc sáu giờ.']::text[], null, 'a3c98772ae2256bec69fbbbedfbf7150683fc711') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('b68892be-6d10-56d4-acb6-3a53ecfd00d1', '8050f34f-24a2-5b41-80b0-f1d22ffc570f', 2, 'We eat dinner, then we watch TV.', array['We eat dinner. Then we watch TV.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('b68892be-6d10-56d4-acb6-3a53ecfd00d1', 'vi', 'Chúng tôi ăn tối, sau đó xem ti vi.', array['Chúng tôi ăn tối rồi xem ti vi.', 'Chúng tôi ăn tối, sau đó chúng tôi xem ti vi.', 'Chúng tôi ăn tối, rồi xem tivi.', 'Chúng mình ăn tối, sau đó xem ti vi.', 'Chúng tôi ăn tối, sau đó xem truyền hình.']::text[], null, 'be1f2540c3b9eba7a43b4fe3e1adc3413022da73') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('d613dd7f-2e0c-5e4d-a1db-1db3e1c93c9f', '8050f34f-24a2-5b41-80b0-f1d22ffc570f', 3, 'I take a shower before dinner.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('d613dd7f-2e0c-5e4d-a1db-1db3e1c93c9f', 'vi', 'Tôi tắm trước bữa tối.', array['Tôi tắm trước khi ăn tối.', 'Tôi đi tắm trước bữa tối.', 'Tôi tắm trước giờ ăn tối.']::text[], null, 'c7b95b85903d980563796131478e5d8cdb6abd03') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('a17d8f65-40f7-5caa-b6c6-63ad243dc8a0', '8050f34f-24a2-5b41-80b0-f1d22ffc570f', 4, 'Do you watch TV after dinner? No, I don''t.', array['Do you watch TV after dinner? No, I do not.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a17d8f65-40f7-5caa-b6c6-63ad243dc8a0', 'vi', 'Bạn có xem ti vi sau bữa tối không? Không, tôi không xem.', array['Sau bữa tối bạn có xem ti vi không? Không, tôi không xem.', 'Bạn có xem ti vi sau khi ăn tối không? Không, tôi không xem.', 'Bạn có xem tivi sau bữa tối không? Không.', 'Bạn có xem ti vi sau bữa tối không? Không, tôi không.']::text[], 'Trả lời ngắn dùng do, don''t: Yes, I do. No, I don''t. Không trả lời Yes, I watch.', '3984d65816fcadf633d93e5875a2fd6da37d6ab2') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a17d8f65-40f7-5caa-b6c6-63ad243dc8a0', 'en-US', 'Do you watch TV after dinner? No, I don''t.', '{}'::text[], 'Short answers use do: Yes, I do. No, I don''t.', '3984d65816fcadf633d93e5875a2fd6da37d6ab2') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('c8da8b49-36a5-5f8a-af8c-18953c163065', '8050f34f-24a2-5b41-80b0-f1d22ffc570f', 5, 'I go to sleep at eleven every night.', array['I go to sleep at 11 every night.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('c8da8b49-36a5-5f8a-af8c-18953c163065', 'vi', 'Tối nào tôi cũng đi ngủ lúc mười một giờ.', array['Tôi đi ngủ lúc mười một giờ mỗi tối.', 'Đêm nào tôi cũng đi ngủ lúc mười một giờ.', 'Tôi đi ngủ lúc mười một giờ mỗi đêm.', 'Tôi đi ngủ lúc 11 giờ mỗi tối.', 'Hằng đêm tôi đi ngủ lúc mười một giờ.']::text[], 'Go to sleep là đi ngủ; sleep là ngủ.', 'ecb652ce85ba171c90494387d49bf7914ec2cd93') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
