insert into public.lessons (id, unit_id, sort_order, kind) values ('4d8db02e-1fa7-55b7-8902-3b2b07eb9785', (select u.id from public.units u join public.levels l on l.id = u.level_id join public.courses c on c.id = l.course_id where c.slug = 'english' and l.code = 'a1' and u.slug = 'daily-routine'), 4, 'lesson') on conflict (id) do update set sort_order = excluded.sort_order;
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 'vi', 'Bao lâu một lần', 'Trạng từ tần suất, từ nhiều đến ít: always (luôn luôn), usually (thường), often (hay), sometimes (thỉnh thoảng), never (không bao giờ). Chúng đứng trước động từ thường: I usually eat breakfast at home. Nhưng đứng sau be: I''m always busy. Never đã mang nghĩa phủ định, không thêm don''t: nói I never watch TV, không nói I don''t never watch TV. Hỏi bao lâu một lần: How often do you read?', 'Read /riːd/ có âm /iː/ dài; busy /ˈbɪzi/ bắt đầu bằng âm /ɪ/ ngắn, chữ u đọc là i. Often /ˈɔfən/: nhiều người Mỹ không đọc chữ t. Usually /ˈjuʒuəli/ nhấn âm đầu: U-su-al-ly, chữ s đọc /ʒ/; nói nhanh thường chỉ còn ba âm tiết /ˈjuʒəli/. Always /ˈɔlweɪz/ và sometimes /ˈsʌmtaɪmz/ kết thúc bằng âm /z/, đừng bỏ.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
insert into public.lesson_translations (lesson_id, locale, title, grammar_tip, pronunciation_tip) values ('4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 'en-US', 'How often', 'From most to least: always, usually, often, sometimes, never. Put them before a normal verb: I usually eat breakfast at home. Put them after be: I''m always busy. Never is already negative, so do not add don''t: I never watch TV. To ask, say How often do you read?', 'Read has a long /iː/. Busy starts with a short /ɪ/. Many Americans do not say the t in often. In usually, the first part is strong: U-su-al-ly. Always and sometimes end in /z/.') on conflict (lesson_id, locale) do update set title = excluded.title, grammar_tip = excluded.grammar_tip, pronunciation_tip = excluded.pronunciation_tip, status = 'ok';
