insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('d776dde0-55a9-5479-aa58-e855df2f03ce', 'vi', 'thường, thường thường', array['thường', 'thường thường', 'thông thường', 'thường là']::text[], 'Usually ít hơn always: I usually eat breakfast at home nghĩa là phần lớn các ngày, không phải mọi ngày.', '66c2fa4e9e56695791a43a16b1e7e46e2db759e4') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('d776dde0-55a9-5479-aa58-e855df2f03ce', 'en-US', 'most of the time, but not every time', '{}'::text[], 'Usually is less than always: most days, not every day.', '66c2fa4e9e56695791a43a16b1e7e46e2db759e4') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
