insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('c6d87b14-1904-5fd7-9331-c540d4c47a40', 'vi', 'hay, thường xuyên', array['hay', 'thường xuyên', 'thường hay', 'nhiều lần', 'thường']::text[], 'Often ít hơn usually một chút. How often là bao lâu một lần.', '6b77993c34761277d83fe0a20a64053aee43fd20') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('c6d87b14-1904-5fd7-9331-c540d4c47a40', 'en-US', 'many times', '{}'::text[], 'Often is a little less than usually. How often asks how many times.', '6b77993c34761277d83fe0a20a64053aee43fd20') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('78939b27-ba91-5076-83cb-f332c5b8f830', (select id from public.courses where slug = 'english'), 'sometimes', 'adverb', '/ˈsəmˌtaɪmz/', 'B1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('78939b27-ba91-5076-83cb-f332c5b8f830', 'vi', 'thỉnh thoảng, đôi khi', array['thỉnh thoảng', 'đôi khi', 'đôi lúc', 'có khi', 'có lúc']::text[], 'Sometimes có thể đứng đầu câu: Sometimes I read. Đừng nhầm với sometime (một lúc nào đó).', '297f31f02b99ab3fd2219c31def8a1392a5f35b7') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('78939b27-ba91-5076-83cb-f332c5b8f830', 'en-US', 'at some times, but not often', '{}'::text[], 'Sometimes can also start a sentence: Sometimes I read.', '297f31f02b99ab3fd2219c31def8a1392a5f35b7') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('65ee0e8c-a16f-5e12-baac-626807e90a2f', (select id from public.courses where slug = 'english'), 'never', 'adverb', '/ˈnɛvɝ/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('65ee0e8c-a16f-5e12-baac-626807e90a2f', 'vi', 'không bao giờ', array['không bao giờ', 'chẳng bao giờ', 'chưa bao giờ']::text[], 'Never đã là phủ định, không dùng thêm don''t hay not: I never watch TV.', '85777c03b72554cd08e721b6148dc27d2a50a7a6') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('65ee0e8c-a16f-5e12-baac-626807e90a2f', 'en-US', 'not at any time', '{}'::text[], 'Never is already negative. Do not add don''t or not: I never watch TV.', '85777c03b72554cd08e721b6148dc27d2a50a7a6') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.words (id, course_id, lemma, part_of_speech, pronunciation, level_tag) values ('573a32b5-f801-5342-8d83-b27c03482896', (select id from public.courses where slug = 'english'), 'read', 'verb', '/ˈɹid/', 'A1') on conflict (id) do update set pronunciation = excluded.pronunciation, level_tag = excluded.level_tag;
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('573a32b5-f801-5342-8d83-b27c03482896', 'vi', 'đọc', array['đọc', 'đọc sách']::text[], 'Read đọc là /riːd/. Khi nói về quá khứ (học sau), vẫn viết read nhưng đọc /rɛd/, giống red.', 'a7afddb68260a60f86c02a021efba7f216c2e7cf') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.word_translations (word_id, locale, meaning, accepted_forms, usage_note, source_hash) values ('573a32b5-f801-5342-8d83-b27c03482896', 'en-US', 'to look at words and understand them', '{}'::text[], 'Say read like reed. In the past (later), it is still read but sounds like red.', 'a7afddb68260a60f86c02a021efba7f216c2e7cf') on conflict (word_id, locale) do update set meaning = excluded.meaning, accepted_forms = excluded.accepted_forms, usage_note = excluded.usage_note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('7f08b3d4-2c91-5062-8a4f-696701edf974', '4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 1, 'I''m always busy in the morning.', array['I am always busy in the morning.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('7f08b3d4-2c91-5062-8a4f-696701edf974', 'vi', 'Buổi sáng tôi lúc nào cũng bận.', array['Tôi luôn luôn bận vào buổi sáng.', 'Tôi luôn bận vào buổi sáng.', 'Buổi sáng tôi luôn bận rộn.', 'Buổi sáng tôi luôn luôn bận.', 'Sáng nào tôi cũng bận.']::text[], 'Always đứng sau be: I''m always busy, không nói I always am busy.', '393c372d6f88a8ebfabbafbe2cc80a4b043abc75') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('7f08b3d4-2c91-5062-8a4f-696701edf974', 'en-US', 'I''m always busy in the morning.', '{}'::text[], 'Put always after be: I''m always busy.', '393c372d6f88a8ebfabbafbe2cc80a4b043abc75') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('a40e0fd6-f677-5795-b598-5fc54022c6f9', '4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 2, 'I usually eat breakfast at home.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('a40e0fd6-f677-5795-b598-5fc54022c6f9', 'vi', 'Tôi thường ăn sáng ở nhà.', array['Tôi thường ăn sáng tại nhà.', 'Thường thì tôi ăn sáng ở nhà.', 'Tôi thường ăn bữa sáng ở nhà.', 'Tôi thường thường ăn sáng ở nhà.']::text[], null, '9706a5bfce392ac12f3c932c4cd1d683358312b5') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('05d0d160-5590-583b-b57c-7bb4f313752a', '4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 3, 'How often do you read? Sometimes, on the weekend.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('05d0d160-5590-583b-b57c-7bb4f313752a', 'vi', 'Bạn đọc sách bao lâu một lần? Thỉnh thoảng, vào cuối tuần.', array['Bạn có hay đọc sách không? Thỉnh thoảng, vào cuối tuần.', 'Bao lâu bạn đọc sách một lần? Thỉnh thoảng, vào cuối tuần.', 'Bạn có hay đọc sách không? Thỉnh thoảng thôi, vào cuối tuần.', 'Bạn có hay đọc sách không? Đôi khi, vào cuối tuần.', 'Bạn hay đọc sách không? Thỉnh thoảng, vào cuối tuần.', 'Bạn có hay đọc không? Thỉnh thoảng, vào cuối tuần.', 'Bạn có hay đọc sách không? Thỉnh thoảng, vào những ngày cuối tuần.']::text[], 'On the weekend là cách nói của người Mỹ; người Anh nói at the weekend.', 'dffa867ccb2fd71157d5ba17e01dd1e143a69462') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('05d0d160-5590-583b-b57c-7bb4f313752a', 'en-US', 'How often do you read? Sometimes, on the weekend.', '{}'::text[], 'On the weekend is American English.', 'dffa867ccb2fd71157d5ba17e01dd1e143a69462') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('372a31c8-3916-514c-9eb2-9dea9f707815', '4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 4, 'We often watch TV after dinner.', '{}'::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('372a31c8-3916-514c-9eb2-9dea9f707815', 'vi', 'Chúng tôi hay xem ti vi sau bữa tối.', array['Chúng tôi hay xem tivi sau bữa tối.', 'Chúng tôi thường xuyên xem ti vi sau bữa tối.', 'Sau bữa tối chúng tôi hay xem ti vi.', 'Chúng tôi hay xem ti vi sau khi ăn tối.', 'Chúng mình hay xem ti vi sau bữa tối.']::text[], null, 'b7f90ca2fca9f60836e24c05e5529dbc575fe41c') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentences (id, lesson_id, sort_order, text, accepted_forms) values ('6e0d1f61-6110-5c64-8a76-1592b091154c', '4d8db02e-1fa7-55b7-8902-3b2b07eb9785', 5, 'I''m never late for work.', array['I am never late for work.']::text[]) on conflict (id) do update set sort_order = excluded.sort_order, text = excluded.text, accepted_forms = excluded.accepted_forms;
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('6e0d1f61-6110-5c64-8a76-1592b091154c', 'vi', 'Tôi không bao giờ đi làm muộn.', array['Tôi không bao giờ đi làm trễ.', 'Tôi chẳng bao giờ đi làm muộn.', 'Tôi không bao giờ đến chỗ làm muộn.', 'Tôi không bao giờ đi làm muộn cả.']::text[], 'Never đứng sau be và đã mang nghĩa phủ định: không nói I''m not never late.', '00aef9e34edddd6e1ace8658df2758bf56f4a642') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
insert into public.sentence_translations (sentence_id, locale, text, accepted_forms, note, source_hash) values ('6e0d1f61-6110-5c64-8a76-1592b091154c', 'en-US', 'I''m never late for work.', '{}'::text[], 'Never comes after be, and it is already negative.', '00aef9e34edddd6e1ace8658df2758bf56f4a642') on conflict (sentence_id, locale) do update set text = excluded.text, accepted_forms = excluded.accepted_forms, note = excluded.note, source_hash = excluded.source_hash, status = 'ok';
